package com.chunkblazer;

import java.util.Set;
import java.util.concurrent.ConcurrentHashMap;

/**
 * Which world bosses the local player is fighting right now, so a boss NPC's death
 * only earns a token when it was "your kill". Only your own damage (a splat of yours
 * above 0) engages a boss: heals, blocks and other players' hits don't. Engagement
 * ends when the boss dies, when you die, and on a world hop or logout, so an old fight
 * can't carry over into someone else's kill later.
 */
final class BossEngagement
{
	private final Set<String> engaged = ConcurrentHashMap.newKeySet();

	/** A hitsplat landed on a boss NPC with this key. */
	void onHitsplat(String bossKey, boolean mine, int amount)
	{
		if (bossKey != null && mine && amount > 0)
		{
			engaged.add(bossKey);
		}
	}

	/** The boss NPC died; true if it counts as your kill. Either way that fight is over. */
	boolean onBossDeath(String bossKey)
	{
		return bossKey != null && engaged.remove(bossKey);
	}

	/** You died, hopped or logged out: drop every fight in progress. */
	void reset()
	{
		engaged.clear();
	}
}

