 */
@Data
@Builder
public class PlayerLoginRequest
{
	/**
	 * The player's RuneScape name.
	 */
	private String rsn;

	/**
	 * SHA-256 hash of the lowercase RSN (for privacy).
	 */
	@SerializedName("rsn_hash")
	private String rsnHash;

	/**
	 * Current client version for compatibility checking.
	 */
	@SerializedName("client_version")
	private String clientVersion;

	/**
	 * The account's stored API key, when the client already has one. The server
	 * authenticates by this secret (not the public rsn_hash) and reconciles a
	 * renamed display name onto the same account, so a name change updates the
	 * account instead of orphaning it. Omitted (null) on a first-ever login.
	 */
	@SerializedName("api_key")
	private String apiKey;

	/**
	 * SHA-256 of RuneLite's per-account id. It stays the same through a name change and
	 * differs per account, so the server can tell a real rename from a different account
	 * holding this key. Null before the client knows the account.
	 */
	@SerializedName("account_hash")
	private String accountHash;
}

