package com.chunkblazer.ui;

import java.awt.Color;
import java.awt.Component;
import java.awt.Dimension;
import java.awt.Font;
import javax.swing.JTextArea;

/**
 * Word-wrapping read-only label for the ChunkBlazer side panel.
 *
 * <p>Why this exists: the side panel originally used
 * {@code <html><body style='width:Npx; word-wrap:break-word'>...</body></html>}
 * inside JLabels. Swing's HTML renderer fixes the JLabel's preferred height
 * based on the requested CSS width, but BoxLayout often ends up giving the
 * label less actual width than the CSS hinted (vertical scrollbar, parent
 * insets, body default margins). The HTML then wraps onto more lines than
 * the precomputed preferred height covers, and the extra lines get clipped
 * silently — sometimes whole words like "in 10" vanish from the middle of
 * a name. Reducing the CSS width only changes which line gets eaten.
 *
 * <p>{@code JTextArea} with {@code setLineWrap(true) + setWrapStyleWord(true)}
 * wraps at the layout-time width and reports its true wrapped height back to
 * BoxLayout, so the visible component always matches what's actually drawn.
 *
 * <p><b>Maintenance rule:</b> if side-panel text wrapping needs adjustment,
 * change it here. Do not reintroduce {@code JLabel + <html>} for task names.
 */
public final class WrappingTextLabel extends JTextArea
{
	/**
	 * @param text the text to display
	 * @param font font to render with
	 * @param foreground text color
	 * @param maxWidth hard cap on width — BoxLayout will not stretch the
	 *                 component beyond this even if siblings are narrower.
	 *                 Required, otherwise BoxLayout will let a long single
	 *                 line make the component wider than the panel.
	 */
	public WrappingTextLabel(String text, Font font, Color foreground, int maxWidth)
	{
		super(text);
		setFont(font);
		setForeground(foreground);
		setLineWrap(true);
		setWrapStyleWord(true);
		setEditable(false);
		setFocusable(false);
		setOpaque(false);
		setBorder(null);
		setHighlighter(null);
		setAlignmentX(Component.LEFT_ALIGNMENT);
		setMaximumSize(new Dimension(maxWidth, Integer.MAX_VALUE));
	}
}

package com.chunkblazer;

import java.lang.reflect.Field;
import java.lang.reflect.Method;
import java.util.List;
import net.runelite.client.config.ConfigManager;
import com.chunkblazer.modules.TaskModuleManager;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.extension.ExtendWith;
import org.mockito.Mock;
import org.mockito.junit.jupiter.MockitoExtension;

import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.ArgumentMatchers.eq;
import static org.mockito.Mockito.*;

/**
 * Steps 1–2 of the RSProfile migration: knowing WHOSE account this is, before
 * writing anything that belongs to them.
 *
 * <p>Storage is still profile-scoped at this stage, so none of these tests are
 * about where data lands. They are about TIMING, which is the part that has to
 * be right before the store can move at all: RuneLite's
 * {@code setRSProfileConfiguration} silently discards writes issued while no
 * account is logged in, so any code path that writes progress before the RS
 * profile exists would lose that write outright once step 3 lands.
 *
 * <p>The three bugs on 2026-07-21 were all ordering bugs. These pin the order.
 */
@ExtendWith(MockitoExtension.class)
class AccountStateAvailabilityTest
{
	private static final String PROFILE_KEY = "1234abcd.STANDARD.Zezima";

	@Mock
	private ChunkBlazerConfig config;

	@Mock
	private ConfigManager configManager;

	// The gated path clears module state on its way out, so this has to exist.
	@Mock
	private TaskModuleManager taskModuleManager;

	private ChunkBlazerPlugin plugin;

	@BeforeEach
	void setUp() throws Exception
	{
		plugin = new ChunkBlazerPlugin();
		setField(plugin, "config", config);
		setField(plugin, "configManager", configManager);
		setField(plugin, "taskModuleManager", taskModuleManager);
	}

	// --- isAccountStateAvailable ------------------------------------------

	@Test
	void stateIsUnavailableWhileNoAccountIsLoggedIn() throws Exception
	{
		when(configManager.getRSProfileKey()).thenReturn(null);
		assertFalse(available());
	}

	@Test
	void stateAvailableOnceAccountKnown() throws Exception
	{
		when(configManager.getRSProfileKey()).thenReturn(PROFILE_KEY);
		assertTrue(available());
	}

	/**
	 * The logout edge, and the reason the destructive logout sync needs its own
	 * guard in step 3. rsProfileKey is driven by AccountHashChanged /
	 * WorldChanged, which are NOT ordered against our GameStateChanged handling,
	 * so it can already be null while we are still reacting to LOGIN_SCREEN.
	 */
	@Test
	void stateGoesUnavailableAgainOnLogout() throws Exception
	{
		when(configManager.getRSProfileKey()).thenReturn(PROFILE_KEY, (String) null);
		assertTrue(available());
		assertFalse(available());
	}

	// --- the accessors ----------------------------------------------------

	/**
	 * A read with no account must yield nothing — and, critically, the CALLER
	 * must not read that as "new account, seed it". Mistaking absence for
	 * emptiness is how a real player gets re-bootstrapped over.
	 */
	@Test
	void readsReturnNothingWhenNoAccountIsKnown() throws Exception
	{
		// getRSProfileConfiguration answers null when no RS profile is active.
		when(configManager.getRSProfileConfiguration("chunkblazer", "unlockedChunks")).thenReturn(null);
		assertNull(getAccountState("unlockedChunks"));
	}

	/**
	 * Now that the store is RSProfile-scoped, a write with no account is a HARD REFUSAL:
	 * setRSProfileConfiguration silently drops such writes, so setAccountState must not
	 * even attempt it. Every real writer runs once the profile is known.
	 */
	@Test
	void writesAreRefusedWhenNoAccountIsKnown() throws Exception
	{
		when(configManager.getRSProfileKey()).thenReturn(null);

		setAccountState("totalPoints", 42);

		verify(configManager, never()).setRSProfileConfiguration(eq("chunkblazer"), eq("totalPoints"), any());
	}

	@Test
	void writesLandNormallyWhenTheAccountIsKnown() throws Exception
	{
		when(configManager.getRSProfileKey()).thenReturn(PROFILE_KEY);

		setAccountState("totalPoints", 42);

		verify(configManager).setRSProfileConfiguration("chunkblazer", "totalPoints", (Object) 42);
	}

	// --- the bootstrap gate -----------------------------------------------

	/**
	 * THE headline behaviour of step 2. loadActiveTasks() both bootstraps
	 * (ensureStartingChunkUnlocked + two migrations) and rolls tasks; running it
	 * account-less writes progress belonging to nobody, which then gets
	 * attributed to whoever logs in next.
	 */
	@Test
	void loadActiveTasksWritesNothingNoAccount() throws Exception
	{
		when(configManager.getRSProfileKey()).thenReturn(null);

		loadActiveTasks();

		verify(configManager, never()).setConfiguration(eq("chunkblazer"), anyString(), any());
	}

	/**
	 * It must not leave the previous account's tasks on screen either — and it
	 * must reach that state by RETURNING EARLY, not by falling through the normal
	 * path.
	 *
	 * <p>The distinction is not academic. Asserting only that activeTasks ends up
	 * empty passes with the gate deleted, because the normal path clears it too;
	 * that version of this test was verified to survive the mutation and was
	 * therefore guaranteeing nothing. Reading the charter-migration flag is the
	 * first config touch AFTER the gate, so its absence pins the early return
	 * specifically.
	 */
	@Test
	void loadActiveTasksBailsWithoutAccount() throws Exception
	{
		when(configManager.getRSProfileKey()).thenReturn(null);

		List<NuzlockeTask> active = activeTasks();
		active.add(new NuzlockeTask());
		assertFalse(active.isEmpty());

		loadActiveTasks();

		verify(configManager, never()).getConfiguration("chunkblazer", "charterSeedStripped");
		verify(taskModuleManager).clearTask();
		verify(taskModuleManager, never()).registerActiveTask(any());

		assertTrue(activeTasks().isEmpty(),
			"a logout or account switch must not leave the previous account's tasks live");
		assertNull(getField(plugin, "activeTask"));
	}

	// --- reflection helpers ------------------------------------------------

	private boolean available() throws Exception
	{
		return (boolean) invoke("isAccountStateAvailable");
	}

	private String getAccountState(String key) throws Exception
	{
		Method m = ChunkBlazerPlugin.class.getDeclaredMethod("getAccountState", String.class);
		m.setAccessible(true);
		return (String) m.invoke(plugin, key);
	}

	private void setAccountState(String key, Object value) throws Exception
	{
		Method m = ChunkBlazerPlugin.class.getDeclaredMethod("setAccountState", String.class, Object.class);
		m.setAccessible(true);
		m.invoke(plugin, key, value);
	}

	private void loadActiveTasks() throws Exception
	{
		invoke("loadActiveTasks");
	}

	@SuppressWarnings("unchecked")
	private List<NuzlockeTask> activeTasks() throws Exception
	{
		return (List<NuzlockeTask>) getField(plugin, "activeTasks");
	}

	private Object invoke(String name) throws Exception
	{
		Method m = ChunkBlazerPlugin.class.getDeclaredMethod(name);
		m.setAccessible(true);
		return m.invoke(plugin);
	}

	private static Object getField(Object target, String name) throws Exception
	{
		Field f = field(target.getClass(), name);
		return f.get(target);
	}

	private static void setField(Object target, String name, Object value) throws Exception
	{
		field(target.getClass(), name).set(target, value);
	}

	private static Field field(Class<?> c, String name) throws Exception
	{
		while (c != null)
		{
			try
			{
				Field f = c.getDeclaredField(name);
				f.setAccessible(true);
				return f;
			}
			catch (NoSuchFieldException ignored)
			{
				c = c.getSuperclass();
			}
		}
		throw new NoSuchFieldException(name);
	}
}

package com.chunkblazer;

import java.lang.reflect.Field;
import java.lang.reflect.Method;
import java.util.Map;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import com.chunkblazer.api.ChunkBlazerApiClient;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.extension.ExtendWith;
import org.mockito.Mock;
import org.mockito.junit.jupiter.MockitoExtension;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertNull;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.ArgumentMatchers.eq;
import static org.mockito.Mockito.lenient;
import static org.mockito.Mockito.never;
import static org.mockito.Mockito.verify;

/**
 * The account API key is a bearer credential. Since the server now returns it only on the
 * FIRST claim of an RSN (security C1 - the public rsn_hash must no longer buy anyone's key),
 * the client persists it PER-ACCOUNT and recovers it from a UUID-format copy-paste field.
 *
 * <p>These tests lock in the C1 invariants:
 * <ol>
 *   <li>A claimed key is stored only per-account (RSProfile) and is NEVER mirrored into the
 *       shared {@code config.apiKey()} slot - that shared slot was the cross-account leak.</li>
 *   <li>A pasted recovery key must be UUID-format; a non-UUID paste is rejected and the box
 *       cleared.</li>
 *   <li>A valid pasted key becomes the pending candidate and is adopted only after the server
 *       confirms it, so it is NOT written into RSProfile at load time.</li>
 *   <li>On login the client uses this account's key, or none, never a previous account's.</li>
 * </ol>
 */
@ExtendWith(MockitoExtension.class)
class ApiKeyPersistenceTest
{
	// Canonical UUIDs: the only shape the server issues and isValidApiKeyFormat accepts.
	private static final String KEY_A = "11111111-1111-1111-1111-111111111111";
	private static final String KEY_B = "22222222-2222-2222-2222-222222222222";
	private static final String KEY_C = "33333333-3333-3333-3333-333333333333";

	@Mock
	private ChunkBlazerConfig config;
	@Mock
	private ConfigManager configManager;
	@Mock
	private ChunkBlazerApiClient apiClient;
	@Mock
	private ClientThread clientThread;

	private ChunkBlazerPlugin plugin;
	private Map<String, String> rsProfile;

	@BeforeEach
	void setUp() throws Exception
	{
		plugin = new ChunkBlazerPlugin();
		setField(plugin, "config", config);
		setField(plugin, "configManager", configManager);
		setField(plugin, "apiClient", apiClient);
		// Needed so the invalid-key branch's chat message (which posts via clientThread)
		// does not NPE. Left unstubbed: invoke() is a no-op, the lambda never runs.
		setField(plugin, "clientThread", clientThread);
		rsProfile = RsProfileTestSupport.install(configManager, config);
	}

	@Test
	void firstClaimKeyIsStoredPerAccountAndNotMirrored() throws Exception
	{
		persist(KEY_A);

		assertEquals(KEY_A, rsProfile.get("apiKey"), "key persisted per-account (RSProfile)");
		// The shared config slot is the cross-account leak: it must NEVER be written.
		verify(configManager, never()).setConfiguration(eq("chunkblazer"), eq("apiKey"), any());
	}

	@Test
	void anAlreadyStoredKeyIsNotRewritten() throws Exception
	{
		rsProfile.put("apiKey", KEY_A);

		persist(KEY_A);

		verify(configManager, never()).setRSProfileConfiguration(eq("chunkblazer"), eq("apiKey"), any());
		verify(configManager, never()).setConfiguration(eq("chunkblazer"), eq("apiKey"), any());
	}

	@Test
	void anEmptyKeyIsIgnored() throws Exception
	{
		persist("");
		persist(null);

		verify(configManager, never()).setRSProfileConfiguration(eq("chunkblazer"), eq("apiKey"), any());
		verify(configManager, never()).setConfiguration(eq("chunkblazer"), eq("apiKey"), any());
	}

	@Test
	void loadUsesPerAccountKeyWhenNoPaste() throws Exception
	{
		rsProfile.put("apiKey", KEY_A);
		lenient().when(config.apiKey()).thenReturn(""); // empty recovery box

		load();

		verify(apiClient).setPlayerApiKey(KEY_A);
		// No paste, so nothing is written back anywhere: no mirror, no self-heal.
		verify(configManager, never()).setConfiguration(eq("chunkblazer"), eq("apiKey"), any());
	}

	@Test
	void pastedKeyLoadsAsPendingOnly() throws Exception
	{
		// RSProfile empty (fresh install / new profile); the player pasted a saved UUID key.
		lenient().when(config.apiKey()).thenReturn("  " + KEY_B + "  ");

		load();

		// Tried on the client (trimmed) as the pending candidate for this login...
		verify(apiClient).setPlayerApiKey(KEY_B);
		// ...but NOT persisted at load: adoption waits for the server to confirm it.
		assertNull(rsProfile.get("apiKey"), "pasted key is not written into RSProfile at load time");
		verify(configManager, never()).setConfiguration(eq("chunkblazer"), eq("apiKey"), any());
	}

	@Test
	void loadRejectsInvalidPastedKeyAndClearsBox() throws Exception
	{
		// RSProfile empty, and the recovery box holds something that is not a UUID.
		lenient().when(config.apiKey()).thenReturn("not-a-real-key");

		load();

		// The garbage paste is wiped from the box so it cannot be retried or override a key.
		verify(configManager).setConfiguration("chunkblazer", "apiKey", "");
		// With no valid key for this account, the client is cleared so it never
		// authenticates as a previously-logged-in account.
		verify(apiClient).setPlayerApiKey(null);
	}

	// --- helpers -----------------------------------------------------------

	private void persist(String key) throws Exception
	{
		Method m = ChunkBlazerPlugin.class.getDeclaredMethod("persistApiKey", String.class);
		m.setAccessible(true);
		m.invoke(plugin, key);
	}

	private void load() throws Exception
	{
		Method m = ChunkBlazerPlugin.class.getDeclaredMethod("loadPersistedApiKey");
		m.setAccessible(true);
		m.invoke(plugin);
	}

	private static void setField(Object target, String name, Object value) throws Exception
	{
		Class<?> c = target.getClass();
		while (c != null)
		{
			try
			{
				Field f = c.getDeclaredField(name);
				f.setAccessible(true);
				f.set(target, value);
				return;
			}
			catch (NoSuchFieldException e)
			{
				c = c.getSuperclass();
			}
		}
		throw new NoSuchFieldException(name);
	}
}

