package com.chunkblazer;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertNull;
import static org.junit.jupiter.api.Assertions.assertTrue;

import net.runelite.api.Skill;
import net.runelite.api.events.StatChanged;
import org.junit.jupiter.api.Test;

/** The "Only tasks I have the level for" filter. */
class LevelFilterTest
{
	private final ChunkBlazerPlugin plugin = new ChunkBlazerPlugin();

	@Test
	void hidesOnlyWhenLevelTooLow()
	{
		NuzlockeTask coal = task("Mining", 30);
		assertTrue(plugin.meetsLevelRequirement(coal), "levels not loaded yet: don't hide");

		plugin.onStatChanged(new StatChanged(Skill.MINING, 0, 20, 20));
		assertFalse(plugin.meetsLevelRequirement(coal));

		plugin.onStatChanged(new StatChanged(Skill.MINING, 0, 30, 30));
		assertTrue(plugin.meetsLevelRequirement(coal));
	}

	@Test
	void nonSkillTasksAlwaysShown()
	{
		plugin.onStatChanged(new StatChanged(Skill.ATTACK, 0, 1, 1));
		assertTrue(plugin.meetsLevelRequirement(task("Combat", 90)));
		assertTrue(plugin.meetsLevelRequirement(task("Quest", 50)));
	}

	@Test
	void categoryNames()
	{
		assertEquals(Skill.RUNECRAFT, ChunkBlazerPlugin.skillForCategory("Runecrafting"));
		assertEquals(Skill.SLAYER, ChunkBlazerPlugin.skillForCategory("Slayer"));
		assertNull(ChunkBlazerPlugin.skillForCategory("Obtain"));
	}

	private static NuzlockeTask task(String category, int level)
	{
		NuzlockeTask t = new NuzlockeTask();
		t.setCategory(category);
		t.setLevel(level);
		return t;
	}
}

package com.chunkblazer;

import java.lang.reflect.Field;
import java.lang.reflect.Method;
import java.util.Map;
import net.runelite.api.Client;
import net.runelite.api.Player;
import net.runelite.client.config.ConfigManager;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.extension.ExtendWith;
import org.mockito.Mock;
import org.mockito.junit.jupiter.MockitoExtension;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertTrue;
import static org.mockito.ArgumentMatchers.anyString;
import static org.mockito.ArgumentMatchers.eq;
import static org.mockito.Mockito.lenient;
import static org.mockito.Mockito.never;
import static org.mockito.Mockito.verify;

/**
 * The one-time move of a legacy account's profile-global progress into its RSProfile store
 * ({@code migrateLegacyGlobalStateToRSProfile}). This is the dangerous step — getting the
 * ownership rules wrong loses real progress — so the branches are covered explicitly, per
 * RSPROFILE-MIGRATION-PLAN.md section 4. Mutation-test the mismatch and already-migrated
 * branches: revert the guard and confirm the matching test fails.
 */
@ExtendWith(MockitoExtension.class)
class MigrationToRsProfileTest
{
	@Mock
	private ChunkBlazerConfig config;
	@Mock
	private ConfigManager configManager;
	@Mock
	private Client client;

	private ChunkBlazerPlugin plugin;
	private Map<String, String> rsProfile;

	@BeforeEach
	void setUp() throws Exception
	{
		plugin = new ChunkBlazerPlugin();
		setField(plugin, "config", config);
		setField(plugin, "configManager", configManager);
		setField(plugin, "client", client);
		rsProfile = RsProfileTestSupport.install(configManager, config);
	}

	// --- the branches ------------------------------------------------------

	@Test
	void legacyStateMigratedAndKept() throws Exception
	{
		loggedInAs("Main");
		legacy("unlockedChunks", "12850,12851");
		legacy("completedTasks", "chop_tree,mine_coal");
		legacy("totalPoints", "42");
		// no accountModeHash / accountStateOwner tag: the common single-account case

		migrate();

		assertEquals("12850,12851", rsProfile.get("unlockedChunks"), "unlocks moved to RSProfile");
		assertEquals("chop_tree,mine_coal", rsProfile.get("completedTasks"), "tasks moved to RSProfile");
		assertEquals("42", rsProfile.get("totalPoints"), "points moved to RSProfile");
		// Section 4.4: the source is kept as the only rollback — never deleted this release.
		verify(configManager, never()).unsetConfiguration(eq("chunkblazer"), anyString());
	}

	@Test
	void migrationIsSkippedOnceTheDestinationHoldsData() throws Exception
	{
		loggedInAs("Main");
		rsProfile.put("unlockedChunks", "12850"); // already migrated (destination present)
		legacy("unlockedChunks", "12850,99999");
		legacy("completedTasks", "should_not_be_copied");

		migrate();

		assertEquals("12850", rsProfile.get("unlockedChunks"), "existing RSProfile data is untouched");
		assertFalse(rsProfile.containsKey("completedTasks"), "a re-run must not copy anything");
	}

	@Test
	void aForeignBlobIsNeitherMigratedNorDeleted() throws Exception
	{
		loggedInAs("Main");
		legacy("unlockedChunks", "12850,12851");
		// The resident global blob is tagged as belonging to a DIFFERENT account.
		legacy("accountModeHash", hashRsn("SomeoneElse") + ":CASUAL");

		migrate();

		assertFalse(rsProfile.containsKey("unlockedChunks"),
			"another account's data must not be adopted into this account's store");
		verify(configManager, never()).unsetConfiguration(eq("chunkblazer"), anyString());
	}

	@Test
	void aBlobTaggedForThisAccountIsMigrated() throws Exception
	{
		loggedInAs("Main");
		legacy("unlockedChunks", "12850,12851");
		legacy("accountModeHash", hashRsn("Main") + ":CASUAL"); // matches the current account

		migrate();

		assertEquals("12850,12851", rsProfile.get("unlockedChunks"), "own tagged data migrates");
	}

	@Test
	void nothingHappensWhenTheLegacyStoreIsEmpty() throws Exception
	{
		loggedInAs("Main");
		// no legacy globals at all

		migrate();

		assertTrue(rsProfile.isEmpty(), "no legacy data means nothing to move");
	}

	// --- helpers -----------------------------------------------------------

	private void migrate() throws Exception
	{
		Method m = ChunkBlazerPlugin.class.getDeclaredMethod("migrateLegacyGlobalStateToRSProfile");
		m.setAccessible(true);
		m.invoke(plugin);
	}

	private void legacy(String key, String value)
	{
		lenient().when(configManager.getConfiguration("chunkblazer", key)).thenReturn(value);
	}

	private void loggedInAs(String rsn)
	{
		Player p = org.mockito.Mockito.mock(Player.class);
		lenient().when(p.getName()).thenReturn(rsn);
		lenient().when(client.getLocalPlayer()).thenReturn(p);
	}

	private String hashRsn(String rsn) throws Exception
	{
		Method m = ChunkBlazerPlugin.class.getDeclaredMethod("hashRsn", String.class);
		m.setAccessible(true);
		return (String) m.invoke(plugin, rsn);
	}

	private static void setField(Object target, String name, Object value) throws Exception
	{
		Class<?> c = target.getClass();
		while (c != null)
		{
			try
			{
				Field f = c.getDeclaredField(name);
				f.setAccessible(true);
				f.set(target, value);
				return;
			}
			catch (NoSuchFieldException e)
			{
				c = c.getSuperclass();
			}
		}
		throw new NoSuchFieldException(name);
	}
}

package com.chunkblazer;

import com.google.gson.Gson;
import org.junit.jupiter.api.Test;

import static org.junit.jupiter.api.Assertions.*;

/**
 * getBossKeys() is what the once-per-boss token logic keys off, so a chunk can host
 * more than one token-boss on one region (the Varrock chunk carries both Scurrius and
 * Bryophyta). It must prefer the boss_keys LIST, fall back to the single boss_key for
 * every existing one-boss chunk (ToA/CoX), and be empty for non-boss chunks.
 */
class NuzlockeChunkBossKeysTest
{
	private static final Gson GSON = new Gson();

	private NuzlockeChunk parse(String json)
	{
		return GSON.fromJson(json, NuzlockeChunk.class);
	}

	@Test
	void bossKeysList_isReturnedWhenPresent()
	{
		NuzlockeChunk c = parse("{\"region_id\":[12854],\"chunk_type\":\"BOSS\","
			+ "\"boss_keys\":[\"scurrius\",\"bryophyta\"]}");
		assertEquals(java.util.Arrays.asList("scurrius", "bryophyta"), c.getBossKeys());
	}

	@Test
	void singleBossKey_fallsBackToOneElementList()
	{
		NuzlockeChunk c = parse("{\"region_id\":[13354],\"chunk_type\":\"BOSS\",\"boss_key\":\"toa\"}");
		assertEquals(java.util.Collections.singletonList("toa"), c.getBossKeys());
	}

	@Test
	void bossKeysListWins_overSingleKey()
	{
		NuzlockeChunk c = parse("{\"chunk_type\":\"BOSS\",\"boss_key\":\"scurrius\","
			+ "\"boss_keys\":[\"scurrius\",\"bryophyta\"]}");
		assertEquals(2, c.getBossKeys().size(), "the list supersedes the single key");
		assertTrue(c.getBossKeys().contains("bryophyta"));
	}

	@Test
	void noBossKeys_isEmpty()
	{
		NuzlockeChunk c = parse("{\"region_id\":[12345],\"chunk_type\":\"Standard\"}");
		assertTrue(c.getBossKeys().isEmpty(), "a non-boss chunk has no boss keys");
	}

	@Test
	void bossNpcIds_parsePerBossKey()
	{
		// The data-driven NPC-death detection: each boss key maps to the npc ids whose
		// death completes it. Drives the plugin's id -> key lookup (no hardcoded map).
		NuzlockeChunk c = parse("{\"chunk_type\":\"BOSS\",\"boss_keys\":[\"scurrius\",\"bryophyta\"],"
			+ "\"boss_npc_ids\":{\"scurrius\":[7221,7222],\"bryophyta\":[8195]}}");
		assertNotNull(c.getBossNpcIds());
		assertEquals(java.util.Arrays.asList(7221, 7222), c.getBossNpcIds().get("scurrius"));
		assertEquals(java.util.Arrays.asList(8195), c.getBossNpcIds().get("bryophyta"));
	}

	@Test
	void bossNpcIds_absentIsNull()
	{
		NuzlockeChunk c = parse("{\"chunk_type\":\"BOSS\",\"boss_key\":\"toa\"}");
		assertNull(c.getBossNpcIds(), "raids leave boss_npc_ids unset (chat-detected)");
	}
}

package com.chunkblazer;

import com.google.gson.Gson;
import java.util.Arrays;
import org.junit.jupiter.api.Test;

import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertNotNull;
import static org.junit.jupiter.api.Assertions.assertNull;
import static org.junit.jupiter.api.Assertions.assertTrue;

/**
 * The group_content flag and the schema rule that keeps it honest.
 *
 * <p>Pairing group_content with a time or equipment constraint produces a task
 * that loads, displays, and rolls — but can never be completed, because the
 * solo-only gates it implies are unsatisfiable in a team. That is an authoring
 * mistake we want caught at load, not by a player who spends an evening on it.
 */
class NuzlockeTaskGroupContentTest
{
	private final Gson gson = new Gson();

	@Test
	void absentFlagMeansSolo()
	{
		NuzlockeTask task = gson.fromJson(
			"{\"name\":\"Defeat a Mugger\",\"taskID\":\"defeat_mugger\"}", NuzlockeTask.class);

		assertFalse(task.isGroupContent(), "a task with no group_content field must default to solo");
		assertNull(task.getGroupContentSchemaError(), "a plain solo task has no schema error");
	}

	@Test
	void flagIsParsedFromJson()
	{
		NuzlockeTask task = gson.fromJson(
			"{\"name\":\"Defeat Nex\",\"taskID\":\"defeat_nex\",\"group_content\":true}", NuzlockeTask.class);

		assertTrue(task.isGroupContent(), "group_content:true must deserialize");
		assertNull(task.getGroupContentSchemaError(), "an unconstrained group task is valid");
	}

	/**
	 * Regression: the custom NuzlockeTaskDeserializer reads every field by hand, so a
	 * NuzlockeTask-level boolean that isn't wired in silently stays null despite its
	 * @SerializedName. require_all_equipped went unread — full-set EQUIP tasks (Barrows,
	 * Moons) completed on a SINGLE piece in production because isRequireAllEquipped()
	 * fell back to false. These parse tests guard the deserializer, unlike the module
	 * tests that call the setter directly.
	 */
	@Test
	void requireAllEquippedIsParsedFromJson()
	{
		NuzlockeTask task = gson.fromJson(
			"{\"name\":\"Verac's set\",\"taskID\":\"barrows_equip_veracs_set\",\"require_all_equipped\":true}",
			NuzlockeTask.class);

		assertTrue(task.isRequireAllEquipped(), "require_all_equipped:true must deserialize");
	}

	@Test
	void requireAllEquippedDefaultsFalseWhenAbsent()
	{
		NuzlockeTask task = gson.fromJson(
			"{\"name\":\"Any piece\",\"taskID\":\"barrows_equip_any_piece\"}", NuzlockeTask.class);

		assertFalse(task.isRequireAllEquipped(), "absent require_all_equipped must default to false (OR semantics)");
	}

	@Test
	void forbidEntryModeIsParsedFromJson()
	{
		NuzlockeTask task = gson.fromJson(
			"{\"name\":\"Stainless\",\"taskID\":\"tob_stainless\",\"forbid_entry_mode\":true}",
			NuzlockeTask.class);

		assertTrue(task.isForbidEntryMode(), "forbid_entry_mode:true must deserialize (ToB Entry-mode gate)");
	}

	@Test
	void groupContentWithTimeLimitIsRejected()
	{
		NuzlockeTask task = new NuzlockeTask();
		task.setTaskId("defeat_nex_fast");
		task.setGroupContent(true);
		TaskConstraints c = new TaskConstraints();
		c.setTimeInTicks(100);
		task.setConstraints(c);

		String problem = task.getGroupContentSchemaError();
		assertNotNull(problem, "group_content + time limit must be reported as a schema error");
		assertTrue(problem.contains("time limit"), "the message should name the offending constraint: " + problem);
	}

	@Test
	void groupContentWithEquipmentConstraintIsRejected()
	{
		NuzlockeTask task = new NuzlockeTask();
		task.setTaskId("defeat_nex_naked");
		task.setGroupContent(true);
		TaskConstraints c = new TaskConstraints();
		c.setForbiddenEquipmentIds(Arrays.asList(1234));
		task.setConstraints(c);

		String problem = task.getGroupContentSchemaError();
		assertNotNull(problem, "group_content + equipment constraint must be reported as a schema error");
		assertTrue(problem.contains("equipment"), "the message should name the offending constraint: " + problem);
	}

	/**
	 * Constraints that don't engage the solo-only gates are fine on group tasks —
	 * a required boss drop is the obvious legitimate case.
	 */
	@Test
	void groupContentWithDropConstraintIsAllowed()
	{
		NuzlockeTask task = new NuzlockeTask();
		task.setTaskId("obtain_nex_unique");
		task.setGroupContent(true);
		TaskConstraints c = new TaskConstraints();
		c.setDroppedItem("Zaryte vambraces");
		c.setDroppedItemIds(Arrays.asList(26235));
		task.setConstraints(c);

		assertNull(task.getGroupContentSchemaError(),
			"a drop constraint doesn't engage the solo gates, so it's valid on group content");
	}

	/** A solo task keeps its constraints — the rule is scoped to group content. */
	@Test
	void soloTaskWithTimeLimitIsUnaffected()
	{
		NuzlockeTask task = new NuzlockeTask();
		task.setTaskId("defeat_mugger_fast");
		TaskConstraints c = new TaskConstraints();
		c.setTimeInTicks(27);
		task.setConstraints(c);

		assertNull(task.getGroupContentSchemaError(), "solo speed tasks must remain valid");
	}
}

