package com.chunkblazer;

import static org.junit.jupiter.api.Assertions.assertTrue;

import java.nio.file.Files;
import java.nio.file.Paths;
import org.junit.jupiter.api.Test;

/** The Hub's displayed version and the build version must match the code's. */
class PluginVersionTest
{
	@Test
	void versionsAgree() throws Exception
	{
		String props = new String(Files.readAllBytes(Paths.get("runelite-plugin.properties")));
		String gradle = new String(Files.readAllBytes(Paths.get("build.gradle")));
		assertTrue(props.contains("version=" + ChunkBlazerPlugin.VERSION), "runelite-plugin.properties");
