package com.chunkblazer;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertTrue;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.Mockito.lenient;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.never;
import static org.mockito.Mockito.verify;

import com.chunkblazer.api.PlayerLoginResponse;
import java.lang.reflect.Field;
import net.runelite.api.Client;
import net.runelite.api.Player;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.extension.ExtendWith;
import org.mockito.Mock;
import org.mockito.junit.jupiter.MockitoExtension;

/** Login reconciliation of the mode lock: the server's lock wins a mismatch. */
@ExtendWith(MockitoExtension.class)
class ServerModeLockTest
{
	private static final String RSN = "Chunkatar";

	@Mock
	private ChunkBlazerConfig config;
	@Mock
	private ConfigManager configManager;
	@Mock
	private Client client;
	@Mock
	private ClientThread clientThread;

	private ChunkBlazerPlugin plugin;

	@BeforeEach
	void setUp() throws Exception
	{
		plugin = new ChunkBlazerPlugin();
		set("config", config);
		set("configManager", configManager);
		set("client", client);
		set("clientThread", clientThread);
		RsProfileTestSupport.install(configManager, config);
		Player p = mock(Player.class);
		lenient().when(p.getName()).thenReturn(RSN);
		lenient().when(client.getLocalPlayer()).thenReturn(p);
	}

	@Test
	void adoptsWhenUnlocked()
	{
		plugin.adoptServerModeLock(login("CASUAL", true), RSN);
		assertLocked(GameMode.CASUAL);
		verify(clientThread, never()).invoke(any(Runnable.class));
	}

	@Test
	void serverOverridesLocalCasual()
	{
		plugin.adoptServerModeLock(login("CASUAL", true), RSN);
		plugin.adoptServerModeLock(login("NUZLOCKE", true), RSN);
		assertLocked(GameMode.NUZLOCKE);
		verify(clientThread).invoke(any(Runnable.class));
	}

	@Test
	void matchingLockIsQuiet()
	{
		plugin.adoptServerModeLock(login("NUZLOCKE", true), RSN);
		plugin.adoptServerModeLock(login("NUZLOCKE", true), RSN);
		assertLocked(GameMode.NUZLOCKE);
		verify(clientThread, never()).invoke(any(Runnable.class));
	}

	@Test
	void unlockedServerKeepsLocal()
	{
		plugin.adoptServerModeLock(login("CASUAL", true), RSN);
		plugin.adoptServerModeLock(login(null, false), RSN);
		assertLocked(GameMode.CASUAL);
	}

	private void assertLocked(GameMode mode)
	{
		assertTrue(plugin.isModeLocked());
		assertEquals(mode, plugin.getGameMode());
	}

	private static PlayerLoginResponse login(String mode, boolean locked)
	{
		PlayerLoginResponse.PlayerData d = new PlayerLoginResponse.PlayerData();
		d.setGameMode(mode);
		d.setModeLocked(locked);
		PlayerLoginResponse r = new PlayerLoginResponse();
		r.setStatus("ok");
		r.setPlayer(d);
		return r;
	}

	private void set(String name, Object value) throws Exception
	{
		Field f = ChunkBlazerPlugin.class.getDeclaredField(name);
		f.setAccessible(true);
		f.set(plugin, value);
	}
}

package com.chunkblazer;

import java.lang.reflect.Field;
import java.lang.reflect.Method;
import java.util.Arrays;
import java.util.Collections;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Set;
import net.runelite.client.config.ConfigManager;
import com.chunkblazer.api.PlayerLoginResponse;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.extension.ExtendWith;
import org.mockito.Mock;
import org.mockito.junit.jupiter.MockitoExtension;

import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;

/**
 * Recovering an account's progress from the server.
 *
 * <p>The design intent is that a reinstall, a lost RuneLite profile, or a new
 * machine must NOT cost progress — the server record is the recovery source.
 * The original "hydrate only when local is empty" rule could never deliver
 * that, because the plugin bootstraps local state before any login response
 * arrives: {@code ensureStartingChunkUnlocked()} writes the Lumbridge region
 * from {@code startUp()} and from every {@code loadActiveTasks()}, and the
 * Global Tasks backfill writes the already-finished quests. Local was never
 * empty, hydration always skipped, and the account was left with the bootstrap
 * alone — 1 chunk instead of 15, observed on 2026-07-21.
 *
 * <p>A union fixes it independently of ordering, which is the point: three
 * separate bugs this session came from assuming startup order.
 */
@ExtendWith(MockitoExtension.class)
class ServerStateMergeTest
{
	// SeaShantyBoy's real server record when a clean profile reduced him to one.
	private static final List<Integer> SERVER_CHUNKS = Arrays.asList(
		12084, 12083, 12340, 12341, 12085, 12339, 11827, 11828,
		12850, 12597, 12598, 12596, 12852, 12853, 11829);

	private static final int LUMBRIDGE = 12850;

	@Mock
	private ChunkBlazerConfig config;

	@Mock
	private ConfigManager configManager;

	private java.util.Map<String, String> writes;

	private ChunkBlazerPlugin plugin;

	@BeforeEach
	void setUp() throws Exception
	{
		plugin = new ChunkBlazerPlugin();
		setField(plugin, "config", config);
		setField(plugin, "configManager", configManager);
		writes = RsProfileTestSupport.install(configManager, config);
	}

	private static void setField(Object target, String name, Object value) throws Exception
	{
		Class<?> c = target.getClass();
		while (c != null)
		{
			try
			{
				Field f = c.getDeclaredField(name);
				f.setAccessible(true);
				f.set(target, value);
				return;
			}
			catch (NoSuchFieldException e)
			{
				c = c.getSuperclass();
			}
		}
		throw new NoSuchFieldException(name);
	}

	private void mergeRegions(PlayerLoginResponse.PlayerData pdata) throws Exception
	{
		Method m = ChunkBlazerPlugin.class.getDeclaredMethod(
			"mergeUnlockedRegionsFromServer", PlayerLoginResponse.PlayerData.class);
		m.setAccessible(true);
		m.invoke(plugin, pdata);
	}

	private void mergeTasks(PlayerLoginResponse.PlayerData pdata) throws Exception
	{
		Method m = ChunkBlazerPlugin.class.getDeclaredMethod(
			"mergeCompletedTasksFromServer", PlayerLoginResponse.PlayerData.class);
		m.setAccessible(true);
		m.invoke(plugin, pdata);
	}

	/** DavidJans: a new device showed the starting 2 Boss Tokens instead of the account's 0. */
	@Test
	void loginAdoptsServerBossTokens() throws Exception
	{
		Method m = ChunkBlazerPlugin.class.getDeclaredMethod("adoptServerBossTokens", PlayerLoginResponse.PlayerData.class);
		m.setAccessible(true);

		writes.put("bossTokens", "2"); // a fresh install's starting grant
		PlayerLoginResponse.PlayerData spent = pdata(null, null);
		spent.setBossTokens(0);
		m.invoke(plugin, spent);
		assertEquals("0", writes.get("bossTokens"), "the server's 0 replaces the install's starting 2");

		writes.put("bossTokens", "2");
		m.invoke(plugin, pdata(null, null));
		assertEquals("2", writes.get("bossTokens"), "an older server sends nothing; the local value stays");
	}

	private PlayerLoginResponse.PlayerData pdata(List<Integer> regions, List<String> tasks)
	{
		PlayerLoginResponse.PlayerData d = new PlayerLoginResponse.PlayerData();
		d.setUnlockedRegions(regions);
		d.setCompletedTasks(tasks);
		return d;
	}

	private Set<String> capturedCsv(String key)
	{
		// Per-account writes land in the RSProfile store (backed by the writes map here).
		String v = writes.get(key);
		assertNotNull(v, "expected a per-account write to '" + key + "'");
		return new LinkedHashSet<>(Arrays.asList(v.split(",")));
	}

	/**
	 * THE incident: a clean profile has bootstrapped Lumbridge only. The old
	 * rule saw non-empty local and skipped, leaving 1 chunk; the destructive
	 * sync then pushed that over the server's 15.
	 */
	@Test
	void bootstrapProfileRecoversChunks() throws Exception
	{
		when(config.unlockedChunks()).thenReturn(String.valueOf(LUMBRIDGE));

		mergeRegions(pdata(SERVER_CHUNKS, null));

		Set<String> merged = capturedCsv("unlockedChunks");
		assertEquals(15, merged.size(), "all 15 server chunks must come back, not just the bootstrap");
		for (Integer region : SERVER_CHUNKS)
		{
			assertTrue(merged.contains(String.valueOf(region)), "missing region " + region);
		}
	}

	/** A true reinstall: nothing local at all. */
	@Test
	void emptyProfileRecoversEveryChunkFromTheServer() throws Exception
	{
		when(config.unlockedChunks()).thenReturn("");

		mergeRegions(pdata(SERVER_CHUNKS, null));

		assertEquals(15, capturedCsv("unlockedChunks").size());
	}

	/**
	 * The other direction, and why this is a union rather than "server wins":
	 * a chunk unlocked offline (or after a failed sync) must survive the login
	 * that restores the server's chunks.
	 */
	@Test
	void localOnlyProgressIsNotLostByTheMerge() throws Exception
	{
		when(config.unlockedChunks()).thenReturn(LUMBRIDGE + ",99999");

		mergeRegions(pdata(SERVER_CHUNKS, null));

		Set<String> merged = capturedCsv("unlockedChunks");
		assertTrue(merged.contains("99999"), "a locally-unlocked chunk must survive the merge");
		assertEquals(16, merged.size(), "15 server chunks plus the local-only one");
	}

	/** No difference means no config write — merging must be idempotent. */
	@Test
	void anAlreadyCompleteLocalStateIsNotRewritten() throws Exception
	{
		StringBuilder all = new StringBuilder();
		for (Integer region : SERVER_CHUNKS)
		{
			if (all.length() > 0)
			{
				all.append(',');
			}
			all.append(region);
		}
		when(config.unlockedChunks()).thenReturn(all.toString());

		mergeRegions(pdata(SERVER_CHUNKS, null));

		assertFalse(writes.containsKey("unlockedChunks"), "no unlockedChunks write expected");
	}

	@Test
	void completedTasksAreUnionedNotReplaced() throws Exception
	{
		// Local holds the quest backfill; the server also knows the chunk tasks.
		when(config.completedTasks()).thenReturn("quest_cooks_assistant,defeat_mugger");

		mergeTasks(pdata(null, Arrays.asList(
			"quest_cooks_assistant", "mine_iron_ore", "burn_oak_logs")));

		Set<String> merged = capturedCsv("completedTasks");
		assertTrue(merged.contains("defeat_mugger"), "local-only task must survive");
		assertTrue(merged.contains("mine_iron_ore"), "server-only task must be restored");
		assertEquals(4, merged.size(), "union, with the shared id counted once");
	}

	@Test
	void anEmptyServerRecordChangesNothing() throws Exception
	{
		mergeRegions(pdata(Collections.emptyList(), null));
		mergeTasks(pdata(null, Collections.emptyList()));

		assertFalse(writes.containsKey("unlockedChunks"), "no unlockedChunks write expected");
		assertFalse(writes.containsKey("completedTasks"), "no completedTasks write expected");
	}

	/**
	 * The safety interlock. Sync is destructive and client-authoritative, so it
	 * must refuse to run until the server's record has been merged — otherwise
	 * a periodic sync racing the login response pushes bootstrap-only state.
	 */
	@Test
	void syncIsBlockedUntilTheServerStateHasBeenMerged() throws Exception
	{
		assertFalse(serverStateMerged(),
			"a fresh session must start un-merged so no sync can fire before login is processed");
	}

	/**
	 * A RuneLite profile switch swaps the plugin's whole local state with no
	 * game login. Observed 2026-07-21: the merge flag earned by the PREVIOUS
	 * profile's login survived the switch, so the 30s sync pushed the
	 * newly-active profile's 1-chunk bootstrap over a server record holding 15.
	 * Merely comparing two profiles destroyed the good one.
	 */
	@Test
	void aProfileSwitchRevokesSyncAuthority() throws Exception
	{
		setServerStateMerged(true);

		plugin.revokeSyncAuthorityForProfileSwitch();

		assertFalse(serverStateMerged(),
			"a profile switch must block syncing until the new profile merges the server record");
	}

	/** The switch must also queue a re-login, or the merge would never happen. */
	@Test
	void aProfileSwitchQueuesAServerRelogin() throws Exception
	{
		setServerStateMerged(true);

		plugin.revokeSyncAuthorityForProfileSwitch();

		Field f = ChunkBlazerPlugin.class.getDeclaredField("pendingServerLogin");
		f.setAccessible(true);
		assertTrue((Boolean) f.get(plugin),
			"without a queued re-login the new profile would never merge and could never sync again");
	}

	private boolean serverStateMerged() throws Exception
	{
		Field f = ChunkBlazerPlugin.class.getDeclaredField("serverStateMerged");
		f.setAccessible(true);
		return (Boolean) f.get(plugin);
	}

	private void setServerStateMerged(boolean value) throws Exception
	{
		Field f = ChunkBlazerPlugin.class.getDeclaredField("serverStateMerged");
		f.setAccessible(true);
		f.set(plugin, value);
	}
}

package com.chunkblazer;

import com.google.gson.Gson;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;

import java.io.ByteArrayOutputStream;
import java.io.InputStream;
import java.nio.charset.StandardCharsets;
import java.util.zip.GZIPInputStream;

/**
 * Test-only reader for the bundled task seed ({@code tasks_catalog.json.gz}).
 *
 * <p>Since the JSON→server migration, the individual {@code *_Tasks.json} /
 * {@code Free_Chunks.json} files no longer ship as standalone classpath resources —
 * they are combined into one gzipped seed keyed by filename, exactly what
 * {@code GET /api/tasks} returns and what {@code CatalogStore} reads offline. The
 * "shipped data" tests validate that bundled content, so they pull each file out of
 * the seed the same way the plugin does: gunzip → parse the combined object →
 * {@code value.toString()} for the requested filename.
 */
public final class ShippedSeed
{
	private static final String SEED_RESOURCE = "/com/chunkblazer/tasks_catalog.json.gz";

	private ShippedSeed()
	{
	}

	/**
	 * The original JSON of one file inside the bundled seed (e.g. "Quest_Tasks.json"),
	 * or {@code null} if the seed or that entry is absent.
	 */
	public static String fileContent(String filename) throws Exception
	{
		try (InputStream is = ShippedSeed.class.getResourceAsStream(SEED_RESOURCE))
		{
			if (is == null)
			{
				return null;
			}
			JsonObject combined = new Gson().fromJson(gunzip(is), JsonObject.class);
			if (combined == null)
			{
				return null;
			}
			JsonElement file = combined.get(filename);
			return file == null ? null : file.toString();
		}
	}

	private static String gunzip(InputStream is) throws Exception
	{
		try (GZIPInputStream gz = new GZIPInputStream(is))
		{
			ByteArrayOutputStream bos = new ByteArrayOutputStream();
			byte[] buf = new byte[8192];
			int n;
			while ((n = gz.read(buf)) != -1)
			{
				bos.write(buf, 0, n);
			}
			return new String(bos.toByteArray(), StandardCharsets.UTF_8);
		}
	}
}

package com.chunkblazer;

import java.lang.reflect.Field;
import net.runelite.client.config.ConfigManager;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.extension.ExtendWith;
import org.mockito.Mock;
import org.mockito.junit.jupiter.MockitoExtension;

import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;

/**
 * The start chunk must be PERSISTED, not merely readable.
 *
 * <p>{@code ChunkBlazerConfig.unlockedChunks()} carries an interface default of
 * {@code "12850"}, so the typed accessor answers "Lumbridge is unlocked" even
 * when the key is absent from stored config. Every reader inside this plugin
 * inherits that default and is therefore correct by accident.
 *
 * <p>The standalone ChunkBlazer GPU addon is not. It reads the key raw across a
 * repo boundary — {@code configManager.getConfiguration("chunkblazer",
 * "unlockedChunks")} — with no access to our defaults, so an absent key reads as
 * an EMPTY unlock set and it greys the entire world, Lumbridge included.
 *
 * <p>Bruh Blazer hit that on 2026-07-27. An account switch unset the key at
 * 21:11:03; the server had no regions for the new account so the merge returned
 * early; {@code ensureStartingChunkUnlocked()} saw the default and concluded
 * there was nothing to write. He walked around a fully grey Lumbridge until
 * 21:16:47, when his first paid unlock finally wrote a concrete value and both
 * chunks lit up at once. A second account in the same session never reproduced
 * it — the server had regions for that one, so the merge wrote them immediately.
 *
 * <p>These tests pin the distinction the accessor cannot express: the mocks for
 * the typed read and the raw read are set independently, which is exactly the
 * state the bug lived in.
 */
@ExtendWith(MockitoExtension.class)
class StartingChunkPersistenceTest
{
	private static final int LUMBRIDGE = 12850;
	private static final String KEY = "unlockedChunks";

	@Mock
	private ChunkBlazerConfig config;

	@Mock
	private ConfigManager configManager;

	private java.util.Map<String, String> writes;

	private ChunkBlazerPlugin plugin;

	@BeforeEach
	void setUp() throws Exception
	{
		plugin = new ChunkBlazerPlugin();
		setField(plugin, "config", config);
		setField(plugin, "configManager", configManager);
		writes = RsProfileTestSupport.install(configManager, config);
	}

	private static void setField(Object target, String name, Object value) throws Exception
	{
		Class<?> c = target.getClass();
		while (c != null)
		{
			try
			{
				Field f = c.getDeclaredField(name);
				f.setAccessible(true);
				f.set(target, value);
				return;
			}
			catch (NoSuchFieldException e)
			{
				c = c.getSuperclass();
			}
		}
		throw new NoSuchFieldException(name);
	}

	/**
	 * Under RSProfile there is ONE stored value, not a typed-accessor-vs-raw split: both
	 * getUnlockedRegionIds and isUnlockedChunksPersisted read the same key. So the stored
	 * value is the single source; {@code typedValue} is kept only for call-site readability.
	 * acStr applies the "12850" default when the value is absent.
	 */
	private void given(String typedValue, String storedValue)
	{
		lenient().when(config.unlockedChunks()).thenReturn(storedValue);
	}

	private String captureWrite()
	{
		String v = writes.get(KEY);
		assertNotNull(v, "expected a per-account write to " + KEY);
		return v;
	}

	private void assertNoWrite()
	{
		assertFalse(writes.containsKey(KEY), "expected no per-account write to " + KEY);
	}

	/**
	 * THE incident. Key unset by the account-switch clear, server had nothing to
	 * merge, accessor still answers "12850" off the default. Must write anyway.
	 */
	@Test
	void absentKeyIsSeeded() throws Exception
	{
		given(String.valueOf(LUMBRIDGE), null);

		plugin.ensureStartingChunkUnlocked();

		assertEquals(String.valueOf(LUMBRIDGE), captureWrite(),
			"an absent key must be persisted, or the GPU addon greys the whole world");
	}

	/** A blank stored value is as invisible to a raw reader as a missing one. */
	@Test
	void blankStoredValueIsAlsoSeeded() throws Exception
	{
		given(String.valueOf(LUMBRIDGE), "   ");

		plugin.ensureStartingChunkUnlocked();

		// The start region is seeded; a leading blank is preserved verbatim but is filtered
		// out on read (getUnlockedRegionIds drops empty entries), so it is harmless.
		assertTrue(captureWrite().contains(String.valueOf(LUMBRIDGE)),
			"start region must be seeded when the stored value was blank");
	}

	/** Already on disk — this runs on every loadActiveTasks, so it must not churn config. */
	@Test
	void alreadyPersistedStartRegionIsNotRewritten() throws Exception
	{
		given(String.valueOf(LUMBRIDGE), String.valueOf(LUMBRIDGE));

		plugin.ensureStartingChunkUnlocked();

		assertNoWrite();
	}

	/** Idempotence with real progress present: seeding must never clobber unlocks. */
	@Test
	void existingUnlocksAreLeftAlone() throws Exception
	{
		given("12850,12851,12595", "12850,12851,12595");

		plugin.ensureStartingChunkUnlocked();

		assertNoWrite();
	}

	/**
	 * A stored set that genuinely lacks the start region still gets it appended,
	 * and keeps everything already there. This is the original contract.
	 *
	 * <p>No raw-read stub: when the typed value is already missing the start
	 * region the first branch decides it, and the persisted-check is never
	 * consulted. Strict stubbing enforces that short-circuit.
	 */
	@Test
	void missingStartRegionIsAppended() throws Exception
	{
		when(config.unlockedChunks()).thenReturn("12851,12595");

		plugin.ensureStartingChunkUnlocked();

		String written = captureWrite();
		assertTrue(written.contains(String.valueOf(LUMBRIDGE)), "start region must be added: " + written);
		assertTrue(written.contains("12851"), "existing unlock lost: " + written);
		assertTrue(written.contains("12595"), "existing unlock lost: " + written);
	}
}

