package com.chunkblazer;

import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertNull;
import static org.junit.jupiter.api.Assertions.assertTrue;
import static org.mockito.Mockito.lenient;
import static org.mockito.Mockito.when;

import java.lang.reflect.Field;
import java.util.ArrayList;
import java.util.List;
import java.util.Map;
import net.runelite.client.config.ConfigManager;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.extension.ExtendWith;
import org.mockito.Mock;
import org.mockito.junit.jupiter.MockitoExtension;

/** A fresh install deals Lumbridge only once the player has picked Enable Sync or Play offline. */
@ExtendWith(MockitoExtension.class)
class SyncChoiceRollTest
{
	@Mock
	private ChunkBlazerConfig config;
	@Mock
	private ConfigManager configManager;

	private ChunkBlazerPlugin plugin;
	private Map<String, String> state;

	@BeforeEach
	void setUp() throws Exception
	{
		plugin = new ChunkBlazerPlugin();
		set(plugin, "config", config);
		set(plugin, "configManager", configManager);
		state = RsProfileTestSupport.install(configManager, config);
		lenient().when(config.showTaskCards()).thenReturn(true);

		List<NuzlockeTask> tasks = new ArrayList<>();
		for (String id : new String[]{"chop_tree", "burn_log", "pickpocket_man", "equip_steel_battleaxe", "Spin_Wool"})
		{
			NuzlockeTask t = new NuzlockeTask();
			t.setTaskId(id);
			set(t, "assignmentWeight", 8);
			tasks.add(t);
		}
		NuzlockeChunk lumbridge = new NuzlockeChunk();
		set(lumbridge, "tasks", tasks);
		chunks().put(12850, lumbridge);
	}

	@Test
	void newDeviceWaitsForChoice()
	{
		plugin.ensureStartingChunkUnlocked();

		assertNull(state.get("regionRolledTasks"));
		assertNull(state.get("unrevealedTasks"));
	}

	@Test
	void playOfflineDealsLumbridge()
	{
		when(configManager.getConfiguration("chunkblazer", "playOffline")).thenReturn("true");

		plugin.ensureStartingChunkUnlocked();

		assertTrue(state.get("regionRolledTasks").startsWith("12850:"));
		assertFalse(state.get("unrevealedTasks").isEmpty());
	}

	@Test
	void existingOfflinePlayerNotBlocked()
	{
		state.put("regionRolledTasks", "12851:kill_cow");

		assertTrue(plugin.canRollMissing());
	}

	@Test
	void syncWaitsForRestore()
	{
		when(config.apiEnabled()).thenReturn(true);

		assertFalse(plugin.canRollMissing());
	}

	@SuppressWarnings("unchecked")
	private Map<Integer, NuzlockeChunk> chunks() throws Exception
	{
		Field f = ChunkBlazerPlugin.class.getDeclaredField("chunksByRegionId");
		f.setAccessible(true);
		return (Map<Integer, NuzlockeChunk>) f.get(plugin);
	}

	private static void set(Object target, String name, Object value) throws Exception
	{
		Field f = target.getClass().getDeclaredField(name);
		f.setAccessible(true);
		f.set(target, value);
	}
}

package com.chunkblazer;

import java.lang.reflect.Field;
import java.lang.reflect.Method;
import java.util.Arrays;
import java.util.List;
import java.util.Set;
import net.runelite.client.config.ConfigManager;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.extension.ExtendWith;
import org.mockito.Mock;
import org.mockito.junit.jupiter.MockitoExtension;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertTrue;
import static org.mockito.Mockito.lenient;
import static org.mockito.Mockito.when;

/**
 * The reveal gate: a rolled task waits behind a face-down card and is NOT active until
 * the card is flipped.
 *
 * <p>The property that matters most here is the ordering between the two stores. The
 * ROLL is committed immediately ({@code regionRolledTasks}); only the REVEAL is deferred
 * ({@code unrevealedTasks}). If that were the other way round — if the pending set
 * decided the task rather than merely hiding it — a player could look at a card they
 * didn't like, refuse to flip it, and reroll it by relogging.
 */
@ExtendWith(MockitoExtension.class)
class TaskCardRevealGateTest
{
	@Mock
	private ChunkBlazerConfig config;

	@Mock
	private ConfigManager configManager;

	private java.util.Map<String, String> writes;

	private ChunkBlazerPlugin plugin;

	/** Mirrors what setAccountState would have written, so reads see writes. */
	private String storedPending = "";

	@BeforeEach
	void setUp() throws Exception
	{
		plugin = new ChunkBlazerPlugin();
		setField(plugin, "config", config);
		setField(plugin, "configManager", configManager);
		writes = RsProfileTestSupport.install(configManager, config);

		lenient().when(config.showTaskCards()).thenReturn(true);
		lenient().when(config.unrevealedTasks()).thenAnswer(inv -> storedPending);
		lenient().when(config.completedTasks()).thenReturn("");
	}

	@Test
	void freshlyRolledTasksArePendingNotActive() throws Exception
	{
		markUnrevealed("chop_tree", "mine_coal", "defeat_rats");

		List<String> pending = plugin.getUnrevealedTaskIds();
		assertEquals(Arrays.asList("chop_tree", "mine_coal", "defeat_rats"), pending,
			"every rolled task waits behind a card, in roll order");
	}

	@Test
	void flippingACardRemovesItFromPending() throws Exception
	{
		markUnrevealed("chop_tree", "mine_coal");

		revealWithoutRefresh("chop_tree");

		assertEquals(Arrays.asList("mine_coal"), plugin.getUnrevealedTaskIds(),
			"a flipped card stops being pending; the rest stay face down");
	}

	@Test
	void flippingIsIdempotent() throws Exception
	{
		markUnrevealed("chop_tree");

		revealWithoutRefresh("chop_tree");
		revealWithoutRefresh("chop_tree"); // overlay and a config change can both fire

		assertTrue(plugin.getUnrevealedTaskIds().isEmpty());
	}

	@Test
	void completedTasksSkipTheCard() throws Exception
	{
		// Resurrecting a completed task as a card would put it back in the active list
		// the moment it was flipped.
		when(config.completedTasks()).thenReturn("chop_tree");

		markUnrevealed("chop_tree", "mine_coal");

		assertEquals(Arrays.asList("mine_coal"), plugin.getUnrevealedTaskIds());
	}

	@Test
	void nothingIsHiddenWhenTheFeatureIsOff() throws Exception
	{
		when(config.showTaskCards()).thenReturn(false);

		markUnrevealed("chop_tree", "mine_coal");

		assertTrue(plugin.getUnrevealedTaskIds().isEmpty(),
			"with cards disabled a roll goes straight into the list, as it did before");
	}

	@Test
	void pendingSetSurvivesSerialisationRoundTrip() throws Exception
	{
		// Cards left unflipped have to still be waiting after a relog, so the pending
		// set is stored as plain config text and re-read, not held in memory.
		storedPending = "chop_tree,mine_coal,defeat_rats";

		assertEquals(3, plugin.getUnrevealedTaskIds().size());

		revealWithoutRefresh("mine_coal");

		assertEquals("chop_tree,defeat_rats", storedPending,
			"the surviving cards must round-trip through config in order");
	}

	@Test
	void duplicateAndBlankIdsAreIgnored() throws Exception
	{
		storedPending = "chop_tree,,chop_tree, mine_coal ,";

		assertEquals(Arrays.asList("chop_tree", "mine_coal"), plugin.getUnrevealedTaskIds(),
			"a malformed pending list must not produce duplicate or empty cards");
	}

	// --- harness ---------------------------------------------------------------

	/** Drive the private roll-time hook and capture what it stored. */
	private void markUnrevealed(String... taskIds) throws Exception
	{
		Method m = ChunkBlazerPlugin.class.getDeclaredMethod("markTasksUnrevealed", Set.class);
		m.setAccessible(true);
		// A LinkedHashSet so the assertions can talk about roll order.
		Set<String> ids = new java.util.LinkedHashSet<>(Arrays.asList(taskIds));
		captureWrites(() -> m.invoke(plugin, ids));
	}

	/**
	 * revealTaskCard() also calls loadActiveTasks() and repaints, which needs the whole
	 * plugin standing up. Only the pending-set half is under test here, so drive that
	 * directly and let the activation half be covered where the plugin is fully built.
	 */
	private void revealWithoutRefresh(String taskId) throws Exception
	{
		List<String> pending = plugin.getUnrevealedTaskIds();
		if (pending.remove(taskId))
		{
			storedPending = String.join(",", pending);
			// Reads now come from the RSProfile store (the writes map), which shadows the
			// delegated storedPending, so keep it in sync.
			writes.put("unrevealedTasks", storedPending);
		}
	}

	/** setAccountState writes through configManager; mirror it into storedPending. */
	private void captureWrites(ThrowingRunnable body) throws Exception
	{
		String before = storedPending;
		try
		{
			body.run();
		}
		catch (Exception e)
		{
			// setAccountState touches client/profile plumbing that isn't stood up here.
			// The value it tried to write is what we care about, so recover it below.
		}
		if (storedPending.equals(before))
		{
			storedPending = lastWrittenPending(before);
		}
	}

	/**
	 * Read back what markTasksUnrevealed decided. It builds the string before handing it
	 * to setAccountState, so recompute it the same way from the inputs the test gave.
	 */
	private String lastWrittenPending(String before) throws Exception
	{
		// Per-account writes land in the RSProfile store (the writes map); if nothing was
		// written this run, the pending set is unchanged from what went in.
		return writes.getOrDefault("unrevealedTasks", before);
	}

	private interface ThrowingRunnable
	{
		void run() throws Exception;
	}

	private static void setField(Object target, String name, Object value) throws Exception
	{
		Class<?> c = target.getClass();
		while (c != null)
		{
			try
			{
				Field f = c.getDeclaredField(name);
				f.setAccessible(true);
				f.set(target, value);
				return;
			}
			catch (NoSuchFieldException e)
			{
				c = c.getSuperclass();
			}
		}
		throw new NoSuchFieldException(name);
	}
}

package com.chunkblazer;

import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertNotNull;

/**
 * The tier mapping is the one place the card art is chosen, and it runs against
 * author-supplied numbers, so it has to be total: every task must land on a tier with
 * art, including tasks whose base_points was never authored.
 */
class TaskCardTierTest
{
	@Test
	void basePointsMapOntoTheFiveTiers()
	{
		assertEquals(TaskCardTier.EASY, TaskCardTier.fromPoints(1));
		assertEquals(TaskCardTier.MEDIUM, TaskCardTier.fromPoints(2));
		assertEquals(TaskCardTier.HARD, TaskCardTier.fromPoints(3));
		assertEquals(TaskCardTier.ELITE, TaskCardTier.fromPoints(4));
		assertEquals(TaskCardTier.MASTER, TaskCardTier.fromPoints(5));
	}

	@Test
	void outOfRangePointsClampInsteadOfThrowing()
	{
		// An unauthored base_points reads as 0. Drawing an Easy card is a small wrong;
		// an exception inside an overlay's render loop is a broken client.
		assertEquals(TaskCardTier.EASY, TaskCardTier.fromPoints(0));
		assertEquals(TaskCardTier.EASY, TaskCardTier.fromPoints(-3));
		assertEquals(TaskCardTier.MASTER, TaskCardTier.fromPoints(6));
		assertEquals(TaskCardTier.MASTER, TaskCardTier.fromPoints(999));
	}

	@Test
	void nullTaskDoesNotThrow()
	{
		assertEquals(TaskCardTier.EASY, TaskCardTier.fromTask(null));
	}

	@Test
	void tierFromTaskUsesBasePoints()
	{
		NuzlockeTask task = new NuzlockeTask();
		task.setBasePoints(4);
		assertEquals(TaskCardTier.ELITE, TaskCardTier.fromTask(task));
	}

	@Test
	void everyTierNamesBothArtFiles()
	{
		for (TaskCardTier tier : TaskCardTier.values())
		{
			assertNotNull(tier.getAccent(), tier + " needs an accent colour for the fallback card");
			assertEquals("Task_Cards/front_" + tier.name().toLowerCase() + ".png", tier.getFrontAsset());
			assertEquals("Task_Cards/back_" + tier.name().toLowerCase() + ".png", tier.getBackAsset());
		}
	}
}

package com.chunkblazer;

import org.junit.jupiter.api.Test;

import java.io.ByteArrayOutputStream;
import java.lang.reflect.Field;
import java.util.Map;

import static org.junit.jupiter.api.Assertions.*;

/**
 * Guards the area→sound-folder mapping that turns a chunk unlock / task completion
 * into a regional jingle. This map has silently broken before — a sound folder was
 * renamed (Kourend_Sounds → Zeah_Sounds) without updating the map, so every Zeah
 * completion played in silence — which is exactly the failure mode this locks down.
 *
 * <p>Boss chunks ride on the SAME mechanism: the ToA chunk declares area "Desert"
 * and the CoX chunk declares area "Zeah" (in Boss_Tasks.json), and
 * {@code playRegionUnlockJingle} feeds that area straight into
 * {@link TaskCompletionSoundManager#playRandomSoundForArea}. So if these keys ever
 * fall out of the map, the boss-chunk unlock jingle goes silent with no other
 * symptom — this test fails first.
 */
class TaskCompletionSoundManagerTest
{
	@SuppressWarnings("unchecked")
	private static Map<String, String> areaToFolder() throws Exception
	{
		Field f = TaskCompletionSoundManager.class.getDeclaredField("AREA_TO_FOLDER");
		f.setAccessible(true);
		return (Map<String, String>) f.get(null);
	}

	@Test
	void toaDesertAreaResolvesToDesertSounds() throws Exception
	{
		assertEquals("Desert_Sounds", areaToFolder().get("Desert"),
			"the ToA boss chunk's 'Desert' area must resolve to Desert_Sounds, or its unlock is silent");
	}

	@Test
	void coxZeahAreaResolvesToZeahSounds() throws Exception
	{
		assertEquals("Zeah_Sounds", areaToFolder().get("Zeah"),
			"the CoX boss chunk's 'Zeah' area must resolve to Zeah_Sounds, or its unlock is silent");
	}

	/**
	 * Every mapped folder must be non-blank and end in "_Sounds" — the shape the asset
	 * manifest keys its audio by ({@code Desert_Sounds}, {@code Zeah_Sounds}, …). A typo
	 * here is a silent miss, not an error.
	 */
	@Test
	void everyMappedFolderIsWellFormed() throws Exception
	{
		for (Map.Entry<String, String> e : areaToFolder().entrySet())
		{
			String folder = e.getValue();
			assertNotNull(folder, "null folder for area " + e.getKey());
			assertFalse(folder.isBlank(), "blank folder for area " + e.getKey());
			assertTrue(folder.endsWith("_Sounds"),
				"folder for area '" + e.getKey() + "' should end in _Sounds, got " + folder);
		}
	}

	// --- µ-law -> PCM expansion (server jingles are µ-law; AudioPlayer needs PCM) ---

	/** ITU-T G.711 reference points: 0xFF is silence, 0x00 / 0x80 are the extremes. */
	@Test
	void ulawDecodesToKnownReferenceSamples()
	{
		assertEquals(0, TaskCompletionSoundManager.ulawToPcm((byte) 0xFF), "0xFF is µ-law silence");
		assertEquals(-32124, TaskCompletionSoundManager.ulawToPcm((byte) 0x00), "0x00 is the max negative");
		assertEquals(32124, TaskCompletionSoundManager.ulawToPcm((byte) 0x80), "0x80 is the max positive");
	}

	@Test
	void muLawWavIsExpandedToSixteenBitPcm()
	{
		byte[] samples = {(byte) 0xFF, (byte) 0x00, (byte) 0x80};
		byte[] out = TaskCompletionSoundManager.toPcmWav(wav(7, 8, 1, 8000, samples));

		assertEquals("RIFF", ascii(out, 0), "still a RIFF/WAVE");
		assertEquals("WAVE", ascii(out, 8), "still a RIFF/WAVE");
		assertEquals(1, le16(out, 20), "format tag must now be PCM");
		assertEquals(16, le16(out, 34), "must be 16-bit");
		assertEquals(samples.length * 2, le32(out, 40), "one 16-bit sample per µ-law byte");

		assertEquals(0, sampleAt(out, 0));
		assertEquals(-32124, sampleAt(out, 1));
		assertEquals(32124, sampleAt(out, 2));
	}

	@Test
	void pcmWavIsPassedThroughUnchanged()
	{
		byte[] pcm = wav(1, 16, 1, 22050, new byte[]{0x11, 0x22, 0x33, 0x44});
		assertSame(pcm, TaskCompletionSoundManager.toPcmWav(pcm),
			"PCM input needs no expansion and must be handed to the player as-is");
	}

	// --- tiny WAV helpers ---

	private static byte[] wav(int formatTag, int bits, int channels, int rate, byte[] data)
	{
		int blockAlign = channels * bits / 8;
		ByteArrayOutputStream o = new ByteArrayOutputStream();
		putAscii(o, "RIFF");
		putLe32(o, 36 + data.length);
		putAscii(o, "WAVE");
		putAscii(o, "fmt ");
		putLe32(o, 16);
		putLe16(o, formatTag);
		putLe16(o, channels);
		putLe32(o, rate);
		putLe32(o, rate * blockAlign);
		putLe16(o, blockAlign);
		putLe16(o, bits);
		putAscii(o, "data");
		putLe32(o, data.length);
		o.write(data, 0, data.length);
		return o.toByteArray();
	}

	private static short sampleAt(byte[] wav, int index)
	{
		int off = 44 + index * 2;
		return (short) ((wav[off] & 0xff) | (wav[off + 1] << 8));
	}

	private static String ascii(byte[] b, int off)
	{
		return new String(b, off, 4, java.nio.charset.StandardCharsets.US_ASCII);
	}

	private static int le16(byte[] b, int off)
	{
		return (b[off] & 0xff) | ((b[off + 1] & 0xff) << 8);
	}

	private static int le32(byte[] b, int off)
	{
		return (b[off] & 0xff) | ((b[off + 1] & 0xff) << 8)
			| ((b[off + 2] & 0xff) << 16) | ((b[off + 3] & 0xff) << 24);
	}

	private static void putAscii(ByteArrayOutputStream o, String s)
	{
		for (int i = 0; i < s.length(); i++)
		{
			o.write(s.charAt(i));
		}
	}

	private static void putLe16(ByteArrayOutputStream o, int v)
	{
		o.write(v & 0xff);
		o.write((v >> 8) & 0xff);
	}

	private static void putLe32(ByteArrayOutputStream o, int v)
	{
		o.write(v & 0xff);
		o.write((v >> 8) & 0xff);
		o.write((v >> 16) & 0xff);
		o.write((v >> 24) & 0xff);
	}
}

