package com.chunkblazer.api;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertNull;
import static org.junit.jupiter.api.Assertions.assertTrue;

import com.google.gson.Gson;
import org.junit.jupiter.api.Test;

class ServerRetryPolicyTest
{
	// Jitter pinned to the midpoint.
	private static ServerBackoff backoff()
	{
		return new ServerBackoff(() -> 0.5);
	}

	@Test
	void classify()
	{
		assertEquals(ApiOutcome.SUCCESS, ApiOutcome.classify(200, null));
		assertEquals(ApiOutcome.SUCCESS, ApiOutcome.classify(201, null));
		assertEquals(ApiOutcome.TRANSIENT, ApiOutcome.classify(0, null));
		assertEquals(ApiOutcome.TRANSIENT, ApiOutcome.classify(408, null));
		assertEquals(ApiOutcome.TRANSIENT, ApiOutcome.classify(500, "internal"));
		assertEquals(ApiOutcome.TRANSIENT, ApiOutcome.classify(503, "guard_unavailable"));
		assertEquals(ApiOutcome.RATE_LIMITED, ApiOutcome.classify(429, null));
		assertEquals(ApiOutcome.AUTH_REJECTED, ApiOutcome.classify(401, "unknown_api_key"));
		assertEquals(ApiOutcome.REGISTRATION_CLOSED, ApiOutcome.classify(403, "registration_closed"));
		assertEquals(ApiOutcome.BLOCKED, ApiOutcome.classify(403, null));
		assertEquals(ApiOutcome.REJECTED, ApiOutcome.classify(400, "bad_request"));
		assertEquals(ApiOutcome.REJECTED, ApiOutcome.classify(409, "destructive_sync_rejected"));
		assertEquals(ApiOutcome.REJECTED, ApiOutcome.classify(302, null));
	}

	@Test
	void isOutage()
	{
		assertTrue(ApiOutcome.TRANSIENT.isOutage());
		assertTrue(ApiOutcome.RATE_LIMITED.isOutage());
		assertTrue(ApiOutcome.BLOCKED.isOutage());
		assertFalse(ApiOutcome.REJECTED.isOutage());
		assertFalse(ApiOutcome.AUTH_REJECTED.isOutage());
		assertFalse(ApiOutcome.REGISTRATION_CLOSED.isOutage());
	}

	@Test
	void doublesToCap()
	{
		ServerBackoff b = backoff();
		long[] expected = {0, 0, 60_000, 120_000, 240_000, 300_000, 300_000};
		for (long delay : expected)
		{
			b.recordFailure(ApiOutcome.TRANSIENT, 0, 1_000);
			assertEquals(1_000 + delay, b.getNextAttemptAtMs());
		}
		for (int i = 0; i < 100; i++)
		{
			b.recordFailure(ApiOutcome.TRANSIENT, 0, 0);
		}
		assertEquals(ServerBackoff.MAX_DELAY_MS, b.getNextAttemptAtMs());
	}

	@Test
	void isReady()
	{
		ServerBackoff b = backoff();
		assertTrue(b.isReady(0));
		for (int i = 0; i < ServerBackoff.GRACE_FAILURES; i++)
		{
			b.recordFailure(ApiOutcome.TRANSIENT, 0, 0);
			assertTrue(b.isReady(0));
		}
		b.recordFailure(ApiOutcome.TRANSIENT, 0, 0);
		assertFalse(b.isReady(59_999));
		assertTrue(b.isReady(60_000));
	}

	@Test
	void successResets()
	{
		ServerBackoff b = backoff();
		for (int i = 0; i < 4; i++)
		{
			b.recordFailure(ApiOutcome.TRANSIENT, 0, 0);
		}
		b.recordSuccess();
		assertEquals(0, b.getConsecutiveFailures());
		assertTrue(b.isReady(0));
		b.recordFailure(ApiOutcome.TRANSIENT, 0, 0);
		assertEquals(0, b.getNextAttemptAtMs());
	}

	@Test
	void refusalWaitsCap()
	{
		ServerBackoff b = backoff();
		b.recordFailure(ApiOutcome.REJECTED, 0, 0);
		assertEquals(ServerBackoff.MAX_DELAY_MS, b.getNextAttemptAtMs());
		ServerBackoff c = backoff();
		c.recordFailure(ApiOutcome.BLOCKED, 0, 0);
		assertEquals(ServerBackoff.MAX_DELAY_MS, c.getNextAttemptAtMs());
	}

	@Test
	void retryAfter()
	{
		ServerBackoff b = backoff();
		b.recordFailure(ApiOutcome.RATE_LIMITED, 120_000, 0);
		assertEquals(120_000, b.getNextAttemptAtMs());

		ServerBackoff c = backoff();
		c.recordFailure(ApiOutcome.RATE_LIMITED, 5_000, 0);
		assertEquals(5_000, c.getNextAttemptAtMs());

		ServerBackoff d = backoff();
		d.recordFailure(ApiOutcome.RATE_LIMITED, 24 * 3_600_000L, 0);
		assertEquals(ServerBackoff.MAX_RETRY_AFTER_MS, d.getNextAttemptAtMs());
	}

	@Test
	void jitter()
	{
		ServerBackoff low = new ServerBackoff(() -> 0.0);
		ServerBackoff high = new ServerBackoff(() -> 1.0);
		for (int i = 0; i <= ServerBackoff.GRACE_FAILURES; i++)
		{
			low.recordFailure(ApiOutcome.TRANSIENT, 0, 0);
			high.recordFailure(ApiOutcome.TRANSIENT, 0, 0);
		}
		assertEquals(48_000, low.getNextAttemptAtMs());
		assertEquals(72_000, high.getNextAttemptAtMs());
	}

	@Test
	void outageNotice()
	{
		ServerBackoff b = backoff();
		for (int i = 1; i < ServerBackoff.OUTAGE_NOTICE_THRESHOLD; i++)
		{
			assertFalse(b.recordFailure(ApiOutcome.TRANSIENT, 0, 0));
		}
		assertTrue(b.recordFailure(ApiOutcome.TRANSIENT, 0, 0));
		assertFalse(b.recordFailure(ApiOutcome.TRANSIENT, 0, 0));
		assertTrue(b.recordSuccess());
		assertFalse(b.recordSuccess());
	}

	@Test
	void refusalNoNotice()
	{
		ServerBackoff b = backoff();
		for (int i = 0; i < 20; i++)
		{
			assertFalse(b.recordFailure(ApiOutcome.REJECTED, 0, 0));
		}
		assertFalse(b.recordSuccess());
	}

	@Test
	void errorCode()
	{
		Gson gson = new Gson();
		assertEquals("registration_closed", ChunkBlazerApiClient.errorCode(gson,
			"{\"status\":\"error\",\"error\":\"registration_closed\",\"message\":\"closed\"}"));
		assertNull(ChunkBlazerApiClient.errorCode(gson, "<html>Attention Required! | Cloudflare</html>"));
		assertNull(ChunkBlazerApiClient.errorCode(gson, ""));
		assertNull(ChunkBlazerApiClient.errorCode(gson, "{\"status\":\"error\"}"));
		assertNull(ChunkBlazerApiClient.errorCode(gson, "{\"error\":{\"nested\":true}}"));
	}

	@Test
	void parseRetryAfter()
	{
		assertEquals(120_000, ChunkBlazerApiClient.parseRetryAfterMs("120"));
		assertEquals(5_000, ChunkBlazerApiClient.parseRetryAfterMs(" 5 "));
		assertEquals(0, ChunkBlazerApiClient.parseRetryAfterMs(null));
		assertEquals(0, ChunkBlazerApiClient.parseRetryAfterMs("0"));
		assertEquals(0, ChunkBlazerApiClient.parseRetryAfterMs("-3"));
		assertEquals(0, ChunkBlazerApiClient.parseRetryAfterMs("Wed, 21 Oct 2026 07:28:00 GMT"));
	}
}

package com.chunkblazer.modules;

import net.runelite.api.Client;
import net.runelite.api.Player;
import net.runelite.api.coords.WorldPoint;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.eventbus.EventBus;
import com.chunkblazer.ChunkBlazerConfig;
import com.chunkblazer.NuzlockeTask;
import com.chunkblazer.RequiredItem;
import com.chunkblazer.RequiredObject;
import com.chunkblazer.TargetNpc;
import com.chunkblazer.TaskConstraints;
import org.mockito.Mock;

import java.util.Collections;
import java.util.List;

import static org.mockito.ArgumentMatchers.any;
import static org.mockito.Mockito.lenient;

/**
 * Base test class with common mock setup for task module tests.
 */
public abstract class AbstractTaskModuleTest
{
	@Mock
	protected Client client;

	@Mock
	protected ClientThread clientThread;

	@Mock
	protected EventBus eventBus;

	@Mock
	protected ChunkBlazerConfig config;

	@Mock
	protected Player localPlayer;

	@Mock
	protected WorldPoint playerLocation;

	@Mock
	protected AbstractTaskModule.TaskCompletionCallback completionCallback;

	/**
	 * Work handed to clientThread.invokeLater(BooleanSupplier) that declined to
	 * run yet. Drained by {@link #tickClientThread()}.
	 */
	protected final List<java.util.function.BooleanSupplier> pendingClientThreadWork = new java.util.ArrayList<>();

	/**
	 * Advance the simulated client thread one tick: retry any deferred work,
	 * dropping whatever now reports done. Use after changing client state that a
	 * readiness gate is waiting on (e.g. the inventory container appearing).
	 */
	protected void tickClientThread()
	{
		pendingClientThreadWork.removeIf(java.util.function.BooleanSupplier::getAsBoolean);
	}

	/**
	 * Common setup for all module tests.
	 * Uses lenient stubbing to avoid UnnecessaryStubbingException.
	 */
	protected void setupCommonMocks()
	{
		// Setup client thread to execute runnables immediately
		lenient().doAnswer(invocation ->
		{
			Runnable runnable = invocation.getArgument(0);
			runnable.run();
			return null;
		}).when(clientThread).invokeLater(any(Runnable.class));

		// The BooleanSupplier form retries on later ticks until it returns true.
		// Modules use it to wait for the login sync (ObtainModule's snapshot/XP
		// seed). Try it once now; if it declines, park it so a test can advance
		// the world and then call tickClientThread() — otherwise a deferred seed
		// could never run and a test would pass for the wrong reason.
		lenient().doAnswer(invocation ->
		{
			java.util.function.BooleanSupplier supplier = invocation.getArgument(0);
			if (!supplier.getAsBoolean())
			{
				pendingClientThreadWork.add(supplier);
			}
			return null;
		}).when(clientThread).invokeLater(any(java.util.function.BooleanSupplier.class));

		// Default the login-readiness probes to "fully logged in and synced" so
		// existing tests behave as before. The cold-start race is covered
		// explicitly in ObtainModuleTest.
		lenient().when(client.getGameState()).thenReturn(net.runelite.api.GameState.LOGGED_IN);
		lenient().when(client.getSkillExperience(net.runelite.api.Skill.HITPOINTS)).thenReturn(1154);

		// Setup local player
		lenient().when(client.getLocalPlayer()).thenReturn(localPlayer);
		lenient().when(localPlayer.getWorldLocation()).thenReturn(playerLocation);
		lenient().when(playerLocation.getRegionID()).thenReturn(12345);

		// Setup config defaults
		lenient().when(config.showChatProgress()).thenReturn(true);
		lenient().when(config.showChatSuccess()).thenReturn(true);
	}

	/**
	 * Create a test task with basic fields.
	 */
	protected NuzlockeTask createTestTask(String name, String taskId, String completionType, int targetQuantity)
	{
		NuzlockeTask task = new NuzlockeTask();
		task.setName(name);
		task.setTaskId(taskId);
		task.setCompletionType(completionType);
		task.setTargetQuantity(targetQuantity);
		task.setCurrentProgress(0);
		task.setCompleted(false);
		return task;
	}

	/**
	 * Create a task with required items.
	 */
	protected NuzlockeTask createTaskWithItems(String name, String taskId, String completionType,
											int targetQuantity, List<Integer> itemIds)
	{
		NuzlockeTask task = createTestTask(name, taskId, completionType, targetQuantity);

		RequiredItem requiredItem = new RequiredItem();
		requiredItem.setItemIds(itemIds);
		requiredItem.setQuantity(targetQuantity);

		task.setRequiredItems(Collections.singletonList(requiredItem));
		return task;
	}

	/**
	 * Create a task with target NPC.
	 */
	protected NuzlockeTask createTaskWithNpc(String name, String taskId, String completionType,
											int targetQuantity, List<Integer> npcIds)
	{
		NuzlockeTask task = createTestTask(name, taskId, completionType, targetQuantity);

		TargetNpc targetNpc = new TargetNpc();
		targetNpc.setNpcIds(npcIds);
		targetNpc.setQuantity(targetQuantity);

		task.setTargetNpc(targetNpc);
		return task;
	}

	/**
	 * Create a task with a required GameObject (e.g. a stall).
	 */
	protected NuzlockeTask createTaskWithRequiredObject(String name, String taskId, String completionType,
													int targetQuantity, List<Integer> objectIds)
	{
		NuzlockeTask task = createTestTask(name, taskId, completionType, targetQuantity);

		RequiredObject ro = new RequiredObject();
		ro.setObjectIds(objectIds);
		ro.setQuantity(targetQuantity);

		task.setRequiredObjects(Collections.singletonList(ro));
		return task;
	}

	/**
	 * Create a task with skill constraints.
	 */
	protected NuzlockeTask createTaskWithSkillConstraint(String name, String taskId, String completionType,
														String skill, int level, int xp)
	{
		NuzlockeTask task = createTestTask(name, taskId, completionType, 1);

		TaskConstraints constraints = new TaskConstraints();
		constraints.setRequiredSkill(skill);
		constraints.setRequiredLevel(level);
		constraints.setRequiredXp(xp);

		task.setConstraints(constraints);
		return task;
	}

	/**
	 * Create a task with varbit constraint.
	 */
	protected NuzlockeTask createTaskWithVarbit(String name, String taskId, int varbitId, int expectedValue)
	{
		NuzlockeTask task = createTestTask(name, taskId, "VARBIT_CHECK", 1);

		TaskConstraints constraints = new TaskConstraints();
		constraints.setVarbitId(varbitId);

		task.setConstraints(constraints);
		task.setVarbitBoolean(expectedValue);

		return task;
	}
}

