	@Test
	void testSeersLap()
	{
		// Seers Rooftop (level 60). Obstacles uniform 9 XP, lap bonus 570.
		// Real-world Seers' first obstacle is ~45 XP, well above the old 30 threshold.
		runOneLap("Seers Lap", "complete_seers_roof",
