	@Test
	void testArdougneLap()
	{
		// Ardougne Rooftop (level 90). Obstacles 11–22 XP — the highest single
		// rooftop obstacle XP we test. Lap bonus 793 XP. This is the course
		// that justifies the 30 threshold being above ~22.
