import net.runelite.client.game.ItemManager;
import com.chunkblazer.NuzlockeTask;
import com.chunkblazer.RequiredItem;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.extension.ExtendWith;
import org.mockito.InjectMocks;
import org.mockito.Mock;
import org.mockito.junit.jupiter.MockitoExtension;

import java.lang.reflect.Field;
import java.util.Arrays;
import java.util.Collections;

import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.ArgumentMatchers.anyInt;
import static org.mockito.Mockito.*;

/**
 * Unit tests for FarmingModule.
 *
 * <p>The verification model under test: a Farming XP drop on the same game
 * tick as a change in the watched item's inventory count credits ONE action.
 * Plant tasks consume the seed/sapling (count drops — allotments burn 3 seeds
 * for one planting); the rake task produces Weeds (count rises).
 */
@ExtendWith(MockitoExtension.class)
class FarmingModuleTest extends AbstractTaskModuleTest
{
	private static final int SWEETCORN_SEED = 5320;
	private static final int WEEDS = 6055;
	private static final int DRAGONFRUIT_SAPLING = 22866;
	private static final int ONION_SEED = 5319;
	private static final int GUAM_SEED = 5291;

	// Mutable game tick returned by the client mock; tests advance it to
	// model the plant-animation gap between item change and marker.
	private int currentTick;

	@Mock
	private ItemManager itemManager;

	@Mock
	private ChatMessageManager chatMessageManager;

	@InjectMocks
	private FarmingModule farmingModule;

	@Mock
	private ItemContainer inventoryContainer;

	@BeforeEach
	void setUp() throws Exception
	{
		setupCommonMocks();

		injectField(farmingModule, "client", client);
		injectField(farmingModule, "clientThread", clientThread);
		injectField(farmingModule, "eventBus", eventBus);
		injectField(farmingModule, "config", config);
		injectField(farmingModule, "itemManager", itemManager);

		farmingModule.setCompletionCallback(completionCallback);

		lenient().when(itemManager.canonicalize(anyInt())).thenAnswer(inv -> inv.getArgument(0));
		lenient().when(client.getTickCount()).thenAnswer(inv -> currentTick);
	}

	private void injectField(Object target, String fieldName, Object value) throws Exception
	{
		for (Class<?> clazz = target.getClass(); clazz != null; clazz = clazz.getSuperclass())
		{
			try
			{
				Field field = clazz.getDeclaredField(fieldName);
				field.setAccessible(true);
				field.set(target, value);
				return;
			}
			catch (NoSuchFieldException ignored)
			{
				// walk up
			}
		}
	}

	private NuzlockeTask farmingTask(String name, String taskId, int itemId, int target)
	{
		NuzlockeTask task = new NuzlockeTask();
		task.setName(name);
		task.setTaskId(taskId);
		task.setCategory("Farming");
		task.setCompletionType("FARMING");
		task.setCurrentProgress(0);
		task.setCompleted(false);
		RequiredItem item = new RequiredItem();
		item.setItemIds(Arrays.asList(itemId));
		item.setQuantity(1);
		task.setRequiredItems(Collections.singletonList(item));
		task.setTargetQuantity(target);
		return task;
	}

	private Item itemOf(int itemId, int quantity)
	{
		Item item = mock(Item.class);
		lenient().when(item.getId()).thenReturn(itemId);
		lenient().when(item.getQuantity()).thenReturn(quantity);
		return item;
	}

	private void setInventory(Item... items)
	{
		lenient().when(client.getItemContainer(InventoryID.INV)).thenReturn(inventoryContainer);
		lenient().when(inventoryContainer.getItems()).thenReturn(items);
	}

	@Test
	void testGetCompletionType()
	{
		assertEquals("FARMING", farmingModule.getCompletionType());
	}

	@Test
	void testCanHandle_FarmingTypeAndCategory()
	{
		assertTrue(farmingModule.canHandle(farmingTask("Plant some Sweetcorn", "plant_sweetcorn_seed", SWEETCORN_SEED, 1)));

		NuzlockeTask wrongType = new NuzlockeTask();
		wrongType.setCompletionType("OBTAIN");
		wrongType.setCategory("Obtain");
		assertFalse(farmingModule.canHandle(wrongType));
	}

	@Test
	void plantingSeedWithFarmingXpCompletesTask()
	{
		NuzlockeTask task = farmingTask("Plant some Sweetcorn", "plant_sweetcorn_seed", SWEETCORN_SEED, 1);

		// 5 seeds in a stack at task-load time (baseline snapshot).
		Item seedStack = itemOf(SWEETCORN_SEED, 5);
		setInventory(seedStack);
		farmingModule.addActiveTask(task);

		// One planting: allotment consumes 3 seeds, Farming XP fires same tick
		// (XP first, then the container event — the gathering-style order).
		setInventory(itemOf(SWEETCORN_SEED, 2));
		farmingModule.onStatChanged(new StatChanged(Skill.FARMING, 17, 20, 20));

		assertEquals(1, task.getCurrentProgress());
		assertTrue(task.isCompleted(), "one planting must complete a target-1 plant task");
		verify(completionCallback).onTaskCompleted(task, 1);
	}

	@Test
	void itemChangeBeforeXpSameTickStillCredits()
	{
		NuzlockeTask task = farmingTask("Plant some Sweetcorn", "plant_sweetcorn_seed", SWEETCORN_SEED, 1);

		setInventory(itemOf(SWEETCORN_SEED, 5));
		farmingModule.addActiveTask(task);

		// Container event fires FIRST this tick — no XP yet, so nothing credits
		// and the baseline must NOT move.
		setInventory(itemOf(SWEETCORN_SEED, 2));
		farmingModule.onItemContainerChanged(new ItemContainerChanged(InventoryID.INV, inventoryContainer));
		assertEquals(0, task.getCurrentProgress());

		// The XP drop lands later the same tick — the pending delta credits now.
		farmingModule.onStatChanged(new StatChanged(Skill.FARMING, 17, 20, 20));
		assertEquals(1, task.getCurrentProgress());
		assertTrue(task.isCompleted());
	}

	@Test
	void allotmentCreditsOneActionNotSeeds()
	{
		// Hypothetical "plant twice" task: a single 3-seed planting must credit
		// one ACTION, not three items.
		NuzlockeTask task = farmingTask("Plant some Sweetcorn twice", "plant_sweetcorn_twice", SWEETCORN_SEED, 2);

		setInventory(itemOf(SWEETCORN_SEED, 6));
		farmingModule.addActiveTask(task);

		setInventory(itemOf(SWEETCORN_SEED, 3));
		farmingModule.onStatChanged(new StatChanged(Skill.FARMING, 17, 20, 20));

		assertEquals(1, task.getCurrentProgress(), "3 consumed seeds = 1 planting action");
		assertFalse(task.isCompleted());

		// Second planting on a later tick completes it.
		farmingModule.onGameTick(new GameTick());
		setInventory(itemOf(SWEETCORN_SEED, 0));
		farmingModule.onStatChanged(new StatChanged(Skill.FARMING, 34, 20, 20));

		assertEquals(2, task.getCurrentProgress());
		assertTrue(task.isCompleted());
	}

	@Test
	void bankingSeedsWithoutXpDoesNotCredit()
	{
		NuzlockeTask task = farmingTask("Plant some Sweetcorn", "plant_sweetcorn_seed", SWEETCORN_SEED, 1);

		setInventory(itemOf(SWEETCORN_SEED, 5));
		farmingModule.addActiveTask(task);

		// Seeds banked: container change with NO Farming XP this tick.
		currentTick = 0;
		setInventory();
		farmingModule.onItemContainerChanged(new ItemContainerChanged(InventoryID.INV, inventoryContainer));
		assertEquals(0, task.getCurrentProgress());

		farmingModule.onGameTick(new GameTick());

		// A LATER farming XP drop (watering, harvesting — no watched change)
		// must not claim the banked decrease: XP is a same-tick marker only.
		currentTick = 2;
		farmingModule.onStatChanged(new StatChanged(Skill.FARMING, 17, 20, 20));
		assertEquals(0, task.getCurrentProgress());
		assertFalse(task.isCompleted());
	}

	@Test
	void rakingWeedsCompletesRakeTask()
	{
		// The two "Rake a Farming Patch" tasks watch Weeds, which APPEAR in the
		// inventory when raking grants Farming XP — the opposite direction from
		// plant tasks. Any deviation from the baseline counts.
		NuzlockeTask task = farmingTask("Rake a Farming Patch", "rake_farming_patch", WEEDS, 1);

		setInventory();
		farmingModule.addActiveTask(task);

		setInventory(itemOf(WEEDS, 1));
		farmingModule.onStatChanged(new StatChanged(Skill.FARMING, 4, 3, 3));

		assertEquals(1, task.getCurrentProgress());
		assertTrue(task.isCompleted());
	}

	/**
	 * Cruk's Farmers' Guild regression (session_2026-07-10): tree and
	 * fruit-tree SAPLINGS grant no Farming XP on the plant tick, so the
	 * XP marker never fires — the sapling left the inventory and the module
	 * shrugged. The server's "You plant ..." message is the action marker
	 * for those crops.
	 */
	@Test
	void saplingCreditsViaPlantMessage()
	{
		NuzlockeTask task = farmingTask("Plant a Dragonfruit Tree Sapling",
			"plant_dragonfruit_tree_sapling", DRAGONFRUIT_SAPLING, 1);

		setInventory(itemOf(DRAGONFRUIT_SAPLING, 1));
		farmingModule.addActiveTask(task);

		// Plant tick: sapling consumed, ZERO Farming XP, only the SPAM
		// confirmation message (message-after-item order).
		setInventory();
		farmingModule.onItemContainerChanged(new ItemContainerChanged(InventoryID.INV, inventoryContainer));
		assertEquals(0, task.getCurrentProgress(), "item change alone must not credit");

		farmingModule.onChatMessage(plantMessage(ChatMessageType.SPAM,
			"You plant the dragonfruit tree sapling in the fruit tree patch."));

		assertEquals(1, task.getCurrentProgress());
		assertTrue(task.isCompleted(), "sapling plant must complete via the plant message marker");
		verify(completionCallback).onTaskCompleted(task, 1);
	}

	@Test
	void plantMessageFirstSameTickCredits()
	{
		NuzlockeTask task = farmingTask("Plant a Dragonfruit Tree Sapling",
			"plant_dragonfruit_tree_sapling", DRAGONFRUIT_SAPLING, 1);

		setInventory(itemOf(DRAGONFRUIT_SAPLING, 1));
		farmingModule.addActiveTask(task);

		// Message fires first — no delta yet, but the flag is set...
		farmingModule.onChatMessage(plantMessage(ChatMessageType.SPAM,
			"You plant the dragonfruit tree sapling in the fruit tree patch."));
		assertEquals(0, task.getCurrentProgress());

		// ...so the container change later the same tick credits.
		setInventory();
		farmingModule.onItemContainerChanged(new ItemContainerChanged(InventoryID.INV, inventoryContainer));

		assertEquals(1, task.getCurrentProgress());
		assertTrue(task.isCompleted());
	}

	@Test
	void plantMessageAloneDoesNotCredit()
	{
		// Someone plants a DIFFERENT crop: the message fires, the watched
		// sapling is untouched — no credit.
		NuzlockeTask task = farmingTask("Plant a Dragonfruit Tree Sapling",
			"plant_dragonfruit_tree_sapling", DRAGONFRUIT_SAPLING, 1);

		setInventory(itemOf(DRAGONFRUIT_SAPLING, 1));
		farmingModule.addActiveTask(task);

		farmingModule.onChatMessage(plantMessage(ChatMessageType.SPAM,
			"You plant the apple tree sapling in the fruit tree patch."));

		assertEquals(0, task.getCurrentProgress());
		assertFalse(task.isCompleted());
	}

	@Test
	void nonPlantChatMessagesAreIgnored()
	{
		NuzlockeTask task = farmingTask("Plant a Dragonfruit Tree Sapling",
			"plant_dragonfruit_tree_sapling", DRAGONFRUIT_SAPLING, 1);

		setInventory(itemOf(DRAGONFRUIT_SAPLING, 1));
		farmingModule.addActiveTask(task);

		// Wrong type (public chat saying the magic words) must not arm the tick.
		farmingModule.onChatMessage(plantMessage(ChatMessageType.PUBLICCHAT,
			"You plant the dragonfruit tree sapling in the fruit tree patch."));
		// Unrelated game message must not either.
		farmingModule.onChatMessage(plantMessage(ChatMessageType.GAMEMESSAGE,
			"You rake the patch clear of weeds."));

		setInventory();
		farmingModule.onItemContainerChanged(new ItemContainerChanged(InventoryID.INV, inventoryContainer));

		assertEquals(0, task.getCurrentProgress());
	}

	private ChatMessage plantMessage(ChatMessageType type, String message)
	{
		return new ChatMessage(null, type, "", message, null, 0);
	}

	/**
	 * bao's guam/onion regression (session 2026-07-10 20:01): planting
	 * consumes the seeds at the START of the animation (onion 22->19 at tick
	 * 12, no marker) and the "You plant" message arrives at its END (tick 15).
	 * The change must survive as a pending entry across the gap and be
	 * credited by the message.
	 */
	@Test
	void plantGap_laterMessageClaimsChange()
	{
		NuzlockeTask task = farmingTask("Plant some Onions", "plant_onions", ONION_SEED, 1);

		setInventory(itemOf(ONION_SEED, 22));
		farmingModule.addActiveTask(task);

		// Tick 12: 3 seeds consumed, no marker anywhere this tick.
		currentTick = 12;
		setInventory(itemOf(ONION_SEED, 19));
		farmingModule.onItemContainerChanged(new ItemContainerChanged(InventoryID.INV, inventoryContainer));
		assertEquals(0, task.getCurrentProgress(), "no marker yet — must not credit");
		farmingModule.onGameTick(new GameTick());

		// Ticks 13-14: nothing happens; the pending must survive the slides.
		currentTick = 13;
		farmingModule.onGameTick(new GameTick());
		currentTick = 14;
		farmingModule.onGameTick(new GameTick());

		// Tick 15: the plant confirmation lands.
		currentTick = 15;
		farmingModule.onChatMessage(plantMessage(ChatMessageType.SPAM,
			"You plant 3 onion seeds in the allotment."));

		assertEquals(1, task.getCurrentProgress());
		assertTrue(task.isCompleted(), "message must claim the pending seed consumption from tick 12");
		verify(completionCallback).onTaskCompleted(task, 1);
	}

	@Test
	void pendingChangeExpiresOutsideWindow()
	{
		// A watched-seed decrease with NO plant message inside the window
		// (deposited/dropped) must not be claimable by a much later message.
		NuzlockeTask task = farmingTask("Plant some Onions", "plant_onions", ONION_SEED, 1);

		setInventory(itemOf(ONION_SEED, 22));
		farmingModule.addActiveTask(task);

		currentTick = 0;
		setInventory(itemOf(ONION_SEED, 19));
		farmingModule.onItemContainerChanged(new ItemContainerChanged(InventoryID.INV, inventoryContainer));
		for (int t = 0; t <= 6; t++)
		{
			currentTick = t;
			farmingModule.onGameTick(new GameTick());
		}

		currentTick = 10;
		farmingModule.onChatMessage(plantMessage(ChatMessageType.SPAM,
			"You plant 3 onion seeds in the allotment."));

		assertEquals(0, task.getCurrentProgress());
		assertFalse(task.isCompleted());
	}

	@Test
	void withdrawnSeedsNotClaimedByPlant()
	{
		// Withdrawing the watched seeds (count INCREASES) followed by
		// planting a different crop within the window must not credit — only
		// decreases are plant-shaped.
		NuzlockeTask task = farmingTask("Plant a Guam Seed", "plant_guam", GUAM_SEED, 1);

		setInventory();
		farmingModule.addActiveTask(task);

		currentTick = 1;
		setInventory(itemOf(GUAM_SEED, 18));
		farmingModule.onItemContainerChanged(new ItemContainerChanged(InventoryID.INV, inventoryContainer));

		currentTick = 3;
		farmingModule.onChatMessage(plantMessage(ChatMessageType.SPAM,
			"You plant 3 onion seeds in the allotment."));

		assertEquals(0, task.getCurrentProgress());
		assertFalse(task.isCompleted());
	}

	@Test
	void farmingXpAloneDoesNotCredit()
	{
		// Watering / composting / harvesting grant Farming XP but never touch
		// the watched seed.
		NuzlockeTask task = farmingTask("Plant some Sweetcorn", "plant_sweetcorn_seed", SWEETCORN_SEED, 1);

		setInventory(itemOf(SWEETCORN_SEED, 5));
		farmingModule.addActiveTask(task);

		farmingModule.onStatChanged(new StatChanged(Skill.FARMING, 1, 20, 20));

		assertEquals(0, task.getCurrentProgress());
		assertFalse(task.isCompleted());
	}

	@Test
	void onTaskClearedResetsTracking()
	{
		NuzlockeTask task = farmingTask("Plant some Sweetcorn", "plant_sweetcorn_seed", SWEETCORN_SEED, 1);
		setInventory(itemOf(SWEETCORN_SEED, 5));
		farmingModule.addActiveTask(task);
		assertEquals(1, farmingModule.getActiveTasks().size());

		farmingModule.onTaskCleared();
		assertTrue(farmingModule.getActiveTasks().isEmpty());

		// A post-clear planting-shaped tick must not credit the removed task.
		setInventory(itemOf(SWEETCORN_SEED, 2));
		farmingModule.onStatChanged(new StatChanged(Skill.FARMING, 17, 20, 20));
		assertEquals(0, task.getCurrentProgress());
	}

	@Test
	void startUpAndShutDownManageEventBus()
	{
		farmingModule.startUp();
		verify(eventBus).register(farmingModule);
		farmingModule.shutDown();
		verify(eventBus).unregister(farmingModule);
	}
}

package com.chunkblazer.modules;

import net.runelite.api.gameval.InventoryID;
import net.runelite.api.Item;
import net.runelite.api.ItemContainer;
import net.runelite.api.Skill;
import net.runelite.api.Tile;
import net.runelite.api.TileItem;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.events.ItemContainerChanged;
import net.runelite.api.events.ItemDespawned;
import net.runelite.api.events.StatChanged;
import net.runelite.client.chat.ChatMessageManager;
import net.runelite.client.game.ItemManager;
import com.chunkblazer.NuzlockeTask;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.extension.ExtendWith;
import org.mockito.InjectMocks;
import org.mockito.Mock;
import org.mockito.junit.jupiter.MockitoExtension;

import java.lang.reflect.Field;
import java.util.Arrays;

import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.ArgumentMatchers.anyInt;
import static org.mockito.Mockito.*;

/**
 * Unit tests for FiremakingModule.
 * Tests log consumption detection for firemaking tasks.
 */
@ExtendWith(MockitoExtension.class)
class FiremakingModuleTest extends AbstractTaskModuleTest
{
	@Mock
	private ItemManager itemManager;

	@Mock
	private ChatMessageManager chatMessageManager;

	@InjectMocks
	private FiremakingModule firemakingModule;

	@Mock
	private ItemContainer inventoryContainer;

	@BeforeEach
	void setUp() throws Exception
	{
		setupCommonMocks();

		injectField(firemakingModule, "client", client);
		injectField(firemakingModule, "clientThread", clientThread);
		injectField(firemakingModule, "eventBus", eventBus);
		injectField(firemakingModule, "config", config);
		injectField(firemakingModule, "itemManager", itemManager);

		firemakingModule.setCompletionCallback(completionCallback);

		lenient().when(itemManager.canonicalize(anyInt())).thenAnswer(inv -> inv.getArgument(0));
	}

	private void injectField(Object target, String fieldName, Object value) throws Exception
	{
		Field field = findField(target.getClass(), fieldName);
		if (field != null)
		{
			field.setAccessible(true);
			field.set(target, value);
		}
	}

	private Field findField(Class<?> clazz, String fieldName)
	{
		while (clazz != null)
		{
			try
			{
				return clazz.getDeclaredField(fieldName);
			}
			catch (NoSuchFieldException e)
			{
				clazz = clazz.getSuperclass();
			}
		}
		return null;
	}

	@Test
	void testGetCompletionType()
	{
		assertEquals("FIREMAKING", firemakingModule.getCompletionType());
	}

	@Test
	void testCanHandle_FiremakingType()
	{
		NuzlockeTask task = createTestTask("Burn Logs", "burn_logs", "FIREMAKING", 10);
		assertTrue(firemakingModule.canHandle(task));
	}

	@Test
	void testCanHandle_WrongType()
	{
		NuzlockeTask task = createTestTask("Chop Logs", "chop_logs", "WOODCUTTING", 10);
		assertFalse(firemakingModule.canHandle(task));
	}

	@Test
	void testAddActiveTask()
	{
		NuzlockeTask task = createTaskWithItems("Burn Normal Logs", "burn_logs", "FIREMAKING", 10, Arrays.asList(1511));

		when(client.getItemContainer(InventoryID.INV)).thenReturn(inventoryContainer);
		when(inventoryContainer.getItems()).thenReturn(new Item[0]);
		when(client.getSkillExperience(Skill.FIREMAKING)).thenReturn(1000);

		firemakingModule.addActiveTask(task);

		assertEquals(1, firemakingModule.getActiveTasks().size());
	}

	@Test
	void testOnTaskCleared()
	{
		NuzlockeTask task = createTaskWithItems("Burn Normal Logs", "burn_logs", "FIREMAKING", 10, Arrays.asList(1511));

		when(client.getItemContainer(InventoryID.INV)).thenReturn(inventoryContainer);
		when(inventoryContainer.getItems()).thenReturn(new Item[0]);
		when(client.getSkillExperience(Skill.FIREMAKING)).thenReturn(1000);

		firemakingModule.addActiveTask(task);
		firemakingModule.onTaskCleared();

		assertTrue(firemakingModule.getActiveTasks().isEmpty());
	}

	@Test
	void testStartUpRegistersEventBus()
	{
		firemakingModule.startUp();
		verify(eventBus).register(firemakingModule);
	}

	@Test
	void testShutDownUnregistersEventBus()
	{
		firemakingModule.shutDown();
		verify(eventBus).unregister(firemakingModule);
	}

	// ---- Burn detection: tinderbox AND bonfire ----------------------------
	//
	// A burn is "a watched log left the inventory" paired with "Firemaking XP
	// landed". Both lighting methods produce that pair; what differs is the
	// order and spacing of the two events, which is what these pin down.

	private static final int LOGS = 1511;
	private static final int OAK_LOGS = 1521;

	private int currentTick;
	private int firemakingXp;

	/**
	 * Build mock inventory items. Always assign the result to a local BEFORE
	 * passing it to {@code thenReturn} — stubbing these mocks while an outer
	 * {@code when(...)} is still open trips Mockito's UnfinishedStubbing.
	 */
	private Item[] items(int... idQtyPairs)
	{
		Item[] result = new Item[idQtyPairs.length / 2];
		for (int i = 0; i < result.length; i++)
		{
			Item item = mock(Item.class);
			lenient().when(item.getId()).thenReturn(idQtyPairs[i * 2]);
			lenient().when(item.getQuantity()).thenReturn(idQtyPairs[i * 2 + 1]);
			result[i] = item;
		}
		return result;
	}

	/** An ItemContainer reporting exactly these items. */
	private ItemContainer containerOf(int... idQtyPairs)
	{
		Item[] contents = items(idQtyPairs);
		ItemContainer container = mock(ItemContainer.class);
		lenient().when(container.getItems()).thenReturn(contents);
		return container;
	}

	private void fireInventoryChanged(ItemContainer container)
	{
		firemakingModule.onItemContainerChanged(
			new ItemContainerChanged(InventoryID.INV, container));
	}

	/** Start a "burn N logs" task with a starting inventory of that log. */
	private NuzlockeTask startBurnTask(int logId, int target, int startingLogs)
	{
		NuzlockeTask task = createTaskWithItems(
			"Burn Logs", "burn_logs", "FIREMAKING", target, Arrays.asList(logId));

		Item[] startingInventory = items(logId, startingLogs);

		lenient().when(client.getTickCount()).thenAnswer(inv -> currentTick);
		lenient().when(client.getSkillExperience(Skill.FIREMAKING)).thenReturn(firemakingXp);
		lenient().when(inventoryContainer.getItems()).thenReturn(startingInventory);
		lenient().when(client.getItemContainer(InventoryID.INV)).thenReturn(inventoryContainer);

		firemakingModule.addActiveTask(task);
		return task;
	}

	/** Report the inventory now holding {@code remaining} of {@code logId}. */
	private void inventoryNowHolds(int logId, int remaining)
	{
		fireInventoryChanged(containerOf(logId, remaining));
	}

	private void gainFiremakingXp(int amount)
	{
		firemakingXp += amount;
		firemakingModule.onStatChanged(new StatChanged(Skill.FIREMAKING, firemakingXp, 1, 1));
	}

	/** The traditional tinderbox path: the log goes, then the XP lands. */
	@Test
	void consumptionThenXpCreditsTheBurn()
	{
		NuzlockeTask task = startBurnTask(LOGS, 10, 27);

		inventoryNowHolds(LOGS, 26);
		gainFiremakingXp(40);

		assertEquals(1, task.getCurrentProgress(), "a tinderbox burn must credit");
	}

	/**
	 * THE bonfire regression. When the XP is dispatched ahead of the inventory
	 * update, the old rule found nothing banked, discarded the XP, and scored
	 * zero — leaving the task permanently short.
	 */
	@Test
	void xpThenConsumptionCreditsTheBurn()
	{
		NuzlockeTask task = startBurnTask(LOGS, 10, 27);

		gainFiremakingXp(40);
		inventoryNowHolds(LOGS, 26);

		assertEquals(1, task.getCurrentProgress(),
			"a burn must credit even when its XP arrives before the inventory update");
	}

	/**
	 * A bonfire batch can drain logs faster than the XP drops arrive. Every log
	 * consumed inside the match window counts once the XP confirms the burn.
	 */
	@Test
	void bonfireCreditsEveryLogInWindow()
	{
		NuzlockeTask task = startBurnTask(LOGS, 10, 27);

		inventoryNowHolds(LOGS, 26);
		currentTick++;
		inventoryNowHolds(LOGS, 24);
		currentTick++;
		inventoryNowHolds(LOGS, 22);

		gainFiremakingXp(30);

		assertEquals(5, task.getCurrentProgress(), "every log in the batch must count");
	}

	/**
	 * Logs banked, dropped or sold look exactly like a burn at the inventory
	 * layer. They must not ride along on the next genuine burn — the flaw that
	 * made pending consumption accumulate forever.
	 */
	@Test
	void staleConsumptionDoesNotRideAlongOnALaterBurn()
	{
		NuzlockeTask task = startBurnTask(LOGS, 10, 27);

		// Bank 20 logs — no Firemaking XP accompanies this.
		inventoryNowHolds(LOGS, 7);

		// Much later, genuinely burn one.
		currentTick += 50;
		inventoryNowHolds(LOGS, 6);
		gainFiremakingXp(40);

		assertEquals(1, task.getCurrentProgress(),
			"only the burned log counts; the 20 banked logs must have expired");
	}

	/** Consumption of a log the task doesn't ask for is not progress. */
	@Test
	void unwatchedLogTypeIsIgnored()
	{
		NuzlockeTask task = startBurnTask(LOGS, 10, 27);

		fireInventoryChanged(containerOf(LOGS, 27, OAK_LOGS, 4));
		fireInventoryChanged(containerOf(LOGS, 27, OAK_LOGS, 3));

		gainFiremakingXp(60);

		assertEquals(0, task.getCurrentProgress(), "burning oak must not advance a normal-logs task");
	}

	/** Firemaking XP with no log consumed at all credits nothing. */
	@Test
	void xpWithoutConsumptionCreditsNothing()
	{
		NuzlockeTask task = startBurnTask(LOGS, 10, 27);

		gainFiremakingXp(40);

		assertEquals(0, task.getCurrentProgress());
	}

	/** Reaching the target completes the task and fires the callback. */
	@Test
	void reachingTargetCompletesTheTask()
	{
		NuzlockeTask task = startBurnTask(LOGS, 3, 27);

		int remaining = 27;
		for (int i = 0; i < 3; i++)
		{
			remaining--;
			inventoryNowHolds(LOGS, remaining);
			gainFiremakingXp(40);
			currentTick++;
		}

		assertTrue(task.isCompleted(), "burning the target count must complete the task");
		verify(completionCallback).onTaskCompleted(eq(task), anyInt());
	}

	// ---- Lighting logs on the ground -------------------------------------
	//
	// Sequences below are taken from Mike's 2026-07-28 session, where two burns
	// were lost because the drop-to-light gap outran the match window.

	/** A log despawning off the ground {@code distance} tiles from the player. */
	private void groundLogDespawns(int logId, int distance)
	{
		WorldPoint playerAt = new WorldPoint(3200, 3200, 0);
		lenient().when(localPlayer.getWorldLocation()).thenReturn(playerAt);

		TileItem tileItem = mock(TileItem.class);
		lenient().when(tileItem.getId()).thenReturn(logId);
		lenient().when(tileItem.getQuantity()).thenReturn(1);

		Tile tile = mock(Tile.class);
		lenient().when(tile.getWorldLocation())
			.thenReturn(new WorldPoint(3200 + distance, 3200, 0));

		firemakingModule.onItemDespawned(new ItemDespawned(tile, tileItem));
	}

	/**
	 * THE ground-lighting regression: a log that was never in the inventory.
	 * Nothing is ever consumed, so the old rule had no signal at all.
	 */
	@Test
	void lightingALogAlreadyOnTheGroundCredits()
	{
		NuzlockeTask task = startBurnTask(LOGS, 10, 0);

		groundLogDespawns(LOGS, 0);
		gainFiremakingXp(40);

		assertEquals(1, task.getCurrentProgress(),
			"a log lit off the ground must credit even though none left the inventory");
	}

	/**
	 * Mike's burn #3: dropped at 10:29:32, fire caught 10:29:44. The drop's
	 * consumption has long expired, so the despawn is the only signal left.
	 */
	@Test
	void slowLightOfAnOwnDroppedLogStillCredits()
	{
		NuzlockeTask task = startBurnTask(LOGS, 10, 27);

		inventoryNowHolds(LOGS, 26);   // dropped
		currentTick += 20;             // twelve seconds of walking/lighting
		groundLogDespawns(LOGS, 0);    // fire catches
		gainFiremakingXp(40);

		assertEquals(1, task.getCurrentProgress(),
			"a slow light must credit once, via the despawn");
	}

	/**
	 * Mike's burn #1: dropped and lit immediately. Both signals fire for ONE
	 * log — the inventory consumption is still live, so the despawn must not
	 * add a second credit.
	 */
	@Test
	void quickDropThenLightCreditsOnlyOnce()
	{
		NuzlockeTask task = startBurnTask(LOGS, 10, 27);

		inventoryNowHolds(LOGS, 26);   // dropped
		currentTick += 2;              // two seconds later
		groundLogDespawns(LOGS, 0);    // fire catches
		gainFiremakingXp(40);

		assertEquals(1, task.getCurrentProgress(),
			"drop + despawn describe one log, not two");
	}

	/** Someone else's log vanishing across the room is not our burn. */
	@Test
	void distantGroundDespawnIsIgnored()
	{
		NuzlockeTask task = startBurnTask(LOGS, 10, 0);

		groundLogDespawns(LOGS, 12);
		gainFiremakingXp(40);

		assertEquals(0, task.getCurrentProgress(),
			"a despawn far from the player must not credit");
	}

	/** A ground log of the wrong type still doesn't advance the task. */
	@Test
	void groundDespawnOfUnwatchedLogTypeIsIgnored()
	{
		NuzlockeTask task = startBurnTask(LOGS, 10, 0);

		groundLogDespawns(OAK_LOGS, 0);
		gainFiremakingXp(60);

		assertEquals(0, task.getCurrentProgress());
	}

	/** Picking a log up produces a despawn but no Firemaking XP — no credit. */
	@Test
	void groundDespawnWithoutXpCreditsNothing()
	{
		NuzlockeTask task = startBurnTask(LOGS, 10, 0);

		groundLogDespawns(LOGS, 0);

		assertEquals(0, task.getCurrentProgress());
	}

	/**
	 * One XP gain must pay for exactly one credit. Previously a burn's XP kept
	 * crediting any consumption that landed inside its window, so a log dropped
	 * just after a burn scored on the previous burn's XP.
	 */
	@Test
	void oneXpGainCreditsOnlyOnce()
	{
		NuzlockeTask task = startBurnTask(LOGS, 10, 27);

		inventoryNowHolds(LOGS, 26);
		gainFiremakingXp(40);          // burn #1 credits
		assertEquals(1, task.getCurrentProgress());

		currentTick += 2;
		inventoryNowHolds(LOGS, 25);   // dropped, not yet lit

		assertEquals(1, task.getCurrentProgress(),
			"a drop must not score on the previous burn's XP");
	}

	/** Bonfire ordering must complete a task too, not just score the first log. */
	@Test
	void bonfireOrderingCompletesTheWholeTask()
	{
		NuzlockeTask task = startBurnTask(LOGS, 3, 27);

		int remaining = 27;
		for (int i = 0; i < 3; i++)
		{
			gainFiremakingXp(30);
			remaining--;
			inventoryNowHolds(LOGS, remaining);
			currentTick++;
		}

		assertTrue(task.isCompleted(), "XP-first ordering must be able to finish a task");
	}
}

