		if (field != null)
		{
			field.setAccessible(true);
			field.set(target, value);
		}
	}

	private Field findField(Class<?> clazz, String fieldName)
	{
		while (clazz != null)
		{
			try
			{
				return clazz.getDeclaredField(fieldName);
			}
			catch (NoSuchFieldException e)
			{
				clazz = clazz.getSuperclass();
			}
		}
		return null;
	}

	private NuzlockeTask rung(Skill skill, int level)
	{
		NuzlockeTask task = new NuzlockeTask();
		task.setName("Reach Level " + level + " " + skill.name());
		task.setTaskId("progression_" + skill.name().toLowerCase() + "_" + level);
		task.setCategory("Progression");
		task.setCompletionType("SKILL_THRESHOLD");
		task.setBasePoints(LADDER.get(level));
		task.setTargetQuantity(1);

		TaskConstraints constraints = new TaskConstraints();
		constraints.setRequiredSkill(skill.name());
		constraints.setRequiredLevel(level);
		task.setConstraints(constraints);

		return task;
	}

	// --- Runtime behaviour ------------------------------------------------

	@Test
	void rungCompletesWhenLevelIsReached()
	{
		when(client.getRealSkillLevel(Skill.THIEVING)).thenReturn(29);
		NuzlockeTask task = rung(Skill.THIEVING, 30);
		progressionModule.addActiveTask(task);
		assertFalse(task.isCompleted(), "29 Thieving must not complete the level-30 rung");

		when(client.getRealSkillLevel(Skill.THIEVING)).thenReturn(30);
		progressionModule.onStatChanged(statChanged(Skill.THIEVING, 30));

		assertTrue(task.isCompleted(), "reaching 30 Thieving must complete the rung");
		verify(completionCallback).onTaskCompleted(eq(task), anyInt());
	}

	/**
	 * The reason getRealSkillLevel is used rather than getBoostedSkillLevel: a
	 * stew, a potion, or any temporary boost must not buy a permanent rung.
	 */
	@Test
	void boostedLevelDoesNotCompleteRung()
	{
		when(client.getRealSkillLevel(Skill.MINING)).thenReturn(55);
		lenient().when(client.getBoostedSkillLevel(Skill.MINING)).thenReturn(61);

		NuzlockeTask task = rung(Skill.MINING, 60);
		progressionModule.addActiveTask(task);
		progressionModule.onStatChanged(statChanged(Skill.MINING, 55));

		assertFalse(task.isCompleted(), "a boosted 61 Mining must not complete the level-60 rung");
		verify(completionCallback, never()).onTaskCompleted(any(), anyInt());
	}

	@Test
	void reachedRungCompletesOnRegister()
	{
		// Levelled past an ELIGIBLE rung while the plugin was off — real forward
		// progress we didn't witness, so it still pays.
		when(client.getRealSkillLevel(Skill.HERBLORE)).thenReturn(42);
		NuzlockeTask task = rung(Skill.HERBLORE, 40);

		progressionModule.addActiveTask(task);

		assertTrue(task.isCompleted(), "a rung already passed at registration should settle immediately");
	}

	@Test
	void statChangeInAnotherSkillDoesNotCompleteRung()
	{
		when(client.getRealSkillLevel(Skill.FISHING)).thenReturn(1);
		NuzlockeTask task = rung(Skill.FISHING, 20);
		progressionModule.addActiveTask(task);

		// Cooking XP must not be able to tick a Fishing rung — the cross-credit
		// failure mode that hit the agility tasks.
		progressionModule.onStatChanged(statChanged(Skill.COOKING, 40));

		assertFalse(task.isCompleted(), "a different skill's stat change must not complete this rung");
	}

	@Test
	void taskWithUnknownSkillIsNotTracked()
	{
		NuzlockeTask task = rung(Skill.SLAYER, 50);
		task.getConstraints().setRequiredSkill("NOT_A_SKILL");

		progressionModule.addActiveTask(task);

		assertFalse(progressionModule.getActiveTasks().contains(task),
			"a task naming an unknown skill must not be tracked");
	}

	@Test
	void moduleOnlyHandlesSkillThresholdTasks()
	{
		assertTrue(progressionModule.canHandle(rung(Skill.ATTACK, 40)));

		NuzlockeTask quest = new NuzlockeTask();
		quest.setCompletionType("QUEST_CHECK");
		assertFalse(progressionModule.canHandle(quest), "QUEST_CHECK belongs to QuestCheckModule");
	}

	/** StatChanged(skill, xp, level, boostedLevel) — immutable in this API version. */
	private StatChanged statChanged(Skill skill, int level)
	{
		return new StatChanged(skill, 1, level, level);
	}

	// --- Shipped data -----------------------------------------------------

	private List<NuzlockeTask> loadShippedProgressionTasks() throws Exception
	{
		// Progression_Tasks.json no longer ships as a standalone resource — it rides
		// inside the bundled gzipped seed (the JSON→server migration). Pull it out of
		// the seed the same way CatalogStore does, then parse it exactly as before.
		String json = ShippedSeed.fileContent("Progression_Tasks.json");
		assertNotNull(json, "Progression_Tasks.json is missing from the bundled seed");

		Type mapType = new TypeToken<Map<String, List<NuzlockeChunk>>>()
		{
		}.getType();
		Map<String, List<NuzlockeChunk>> data = new Gson().fromJson(json, mapType);

		assertNotNull(data);
		assertTrue(data.containsKey("Progression_Tasks"),
			"root key should be Progression_Tasks, got " + data.keySet());

		List<NuzlockeChunk> groups = data.get("Progression_Tasks");
		assertNotNull(groups);
		assertEquals(1, groups.size(), "expected exactly one region group");

		List<NuzlockeTask> tasks = groups.get(0).getTasks();
		assertNotNull(tasks, "region group has no tasks array");
		return tasks;
	}

	@Test
	void shippedLadderHasEveryRungForEverySkill() throws Exception
	{
		List<NuzlockeTask> tasks = loadShippedProgressionTasks();

		Map<String, Set<Integer>> bySkill = new HashMap<>();
		for (NuzlockeTask task : tasks)
		{
			assertEquals("SKILL_THRESHOLD", task.getCompletionType(), task.getTaskId());
			assertNotNull(task.getConstraints(), "no constraints on " + task.getTaskId());
			String skill = task.getConstraints().getRequiredSkill();
			assertNotNull(skill, "no required_skill on " + task.getTaskId());
			bySkill.computeIfAbsent(skill, k -> new HashSet<>())
				.add(task.getConstraints().getRequiredLevel());
		}

		assertEquals(24, bySkill.size(), "expected all 24 skills, got " + bySkill.keySet());

		for (Map.Entry<String, Set<Integer>> e : bySkill.entrySet())
		{
			Set<Integer> expected = new HashSet<>(LADDER.keySet());
			if ("HITPOINTS".equals(e.getKey()))
			{
				// Accounts spawn at 10 HP, so that rung would be unearnable.
				expected.remove(10);
			}
			assertEquals(expected, e.getValue(), "wrong rungs for " + e.getKey());
		}

		assertEquals(239, tasks.size(), "24 skills x 10 rungs, minus the impossible Hitpoints 10");
	}

	@Test
	void everyShippedRungMatchesTheDesignedPointLadder() throws Exception
	{
		for (NuzlockeTask task : loadShippedProgressionTasks())
		{
			int level = task.getConstraints().getRequiredLevel();
			assertEquals(LADDER.get(level).intValue(), task.getBasePoints(),
				"base_points off the designed ladder for " + task.getTaskId());
		}
	}

	@Test
	void shippedTaskIdsAreUnique() throws Exception
	{
		List<NuzlockeTask> tasks = loadShippedProgressionTasks();
		Set<String> ids = new HashSet<>();
		List<String> dupes = new ArrayList<>();
		for (NuzlockeTask task : tasks)
		{
			if (!ids.add(task.getTaskId()))
			{
				dupes.add(task.getTaskId());
			}
		}
		assertTrue(dupes.isEmpty(), "duplicate task IDs: " + dupes);
	}

	/**
	 * The Hitpoints level-10 rung must not exist: every account starts at 10 HP,
	 * so shipping it would put a permanently unearnable task in the pool.
	 */
	@Test
	void noHitpointsLevelTenRung() throws Exception
	{
		for (NuzlockeTask task : loadShippedProgressionTasks())
		{
			boolean hpTen = "HITPOINTS".equals(task.getConstraints().getRequiredSkill())
				&& task.getConstraints().getRequiredLevel() == 10;
			assertFalse(hpTen, "Hitpoints 10 is unearnable and must not ship: " + task.getTaskId());
		}
	}

	@Test
	void shippedLadderTotalsTheExpectedPoints() throws Exception
	{
		int total = 0;
		for (NuzlockeTask task : loadShippedProgressionTasks())
		{
			total += task.getBasePoints();
		}
		// 24 skills x 28 points, less the 1-point Hitpoints 10 rung.
		assertEquals(24 * 28 - 1, total, "Progression pool point total changed");
	}
}

package com.chunkblazer.modules;

import com.google.gson.Gson;
import com.google.gson.reflect.TypeToken;
import java.lang.reflect.Field;
import java.lang.reflect.Type;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import net.runelite.api.GameState;
import net.runelite.api.Quest;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.VarbitChanged;
import net.runelite.client.chat.ChatMessageManager;
import com.chunkblazer.NuzlockeChunk;
import com.chunkblazer.ShippedSeed;
import com.chunkblazer.NuzlockeTask;
import com.chunkblazer.TaskConstraints;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.extension.ExtendWith;
import org.mockito.InjectMocks;
import org.mockito.Mock;
import org.mockito.junit.jupiter.MockitoExtension;

import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.ArgumentMatchers.anyInt;
import static org.mockito.Mockito.*;

/**
 * Unit tests for QuestCheckModule and the shipped Quest_Tasks.json ("Global Tasks").
 *
 * Quest.getState() is exercised for real: it calls client.runScript(...) then
 * reads client.getIntStack()[0], both of which are mocked here, so stubbing the
 * int stack to 2 makes any quest report FINISHED.
 */
@ExtendWith(MockitoExtension.class)
class QuestCheckModuleTest extends AbstractTaskModuleTest
{
	private static final String QUEST_TASKS_RESOURCE =
		"/com/chunkblazer/Quest_Tasks.json";

	// QUEST_STATUS_GET result codes, as mapped by Quest.getState().
	private static final int[] STACK_FINISHED = { 2 };
	private static final int[] STACK_NOT_STARTED = { 1 };
	private static final int[] STACK_IN_PROGRESS = { 0 };

	@Mock
	private ChatMessageManager chatMessageManager;

	@InjectMocks
	private QuestCheckModule questCheckModule;

	@BeforeEach
	void setUp() throws Exception
	{
		setupCommonMocks();

		injectField(questCheckModule, "client", client);
		injectField(questCheckModule, "clientThread", clientThread);
		injectField(questCheckModule, "eventBus", eventBus);
		injectField(questCheckModule, "config", config);

		questCheckModule.setCompletionCallback(completionCallback);
	}

	private void injectField(Object target, String fieldName, Object value) throws Exception
	{
		Field field = findField(target.getClass(), fieldName);
		if (field != null)
		{
			field.setAccessible(true);
			field.set(target, value);
		}
	}

	private Field findField(Class<?> clazz, String fieldName)
	{
		while (clazz != null)
		{
			try
			{
				return clazz.getDeclaredField(fieldName);
			}
			catch (NoSuchFieldException e)
			{
				clazz = clazz.getSuperclass();
			}
		}
		return null;
	}

	private NuzlockeTask questTask(String taskId, String questConstant)
	{
		NuzlockeTask task = new NuzlockeTask();
		task.setName("Complete " + questConstant);
		task.setTaskId(taskId);
		task.setCategory("Quest");
		task.setCompletionType("QUEST_CHECK");
		task.setBasePoints(1);
		task.setTargetQuantity(1);

		TaskConstraints constraints = new TaskConstraints();
		constraints.setQuest(questConstant);
		task.setConstraints(constraints);

		return task;
	}

	/**
	 * Drive enough ticks to clear the module's sweep rate limit. Stubs are
	 * lenient: re-stubbing getTickCount each iteration makes every earlier stub
	 * look "unnecessary" to strict Mockito.
	 */
	private void advanceAndSweep()
	{
		questCheckModule.onVarbitChanged(new VarbitChanged());
		for (int i = 1; i <= 12; i++)
		{
			lenient().when(client.getTickCount()).thenReturn(i * 10);
			questCheckModule.onGameTick(new GameTick());
		}
	}

	// ---------------------------------------------------------------
	// Shipped data: the failure this guards against is silent — a bad
	// wrapper shape parses fine and yields zero tasks, and then no quest
	// ever awards a point.
	// ---------------------------------------------------------------

	private List<NuzlockeTask> loadShippedQuestTasks() throws Exception
	{
		// Quest_Tasks.json rides inside the bundled gzipped seed since the JSON→server
		// migration; pull it out the same way CatalogStore does, then parse as before.
		String json = ShippedSeed.fileContent("Quest_Tasks.json");
		assertNotNull(json, "Quest_Tasks.json is missing from the bundled seed");

		Type mapType = new TypeToken<Map<String, List<NuzlockeChunk>>>()
		{
		}.getType();
		Map<String, List<NuzlockeChunk>> data = new Gson().fromJson(json, mapType);

		assertNotNull(data);
		assertTrue(data.containsKey("Quest_Tasks"), "root key should be Quest_Tasks, got " + data.keySet());

		List<NuzlockeChunk> groups = data.get("Quest_Tasks");
		assertNotNull(groups);
		assertEquals(1, groups.size(), "expected exactly one region group");

		List<NuzlockeTask> tasks = groups.get(0).getTasks();
		assertNotNull(tasks, "region group has no tasks array");
		return tasks;
	}

	@Test
	void shippedQuestTasksFileLoadsTasks() throws Exception
	{
		List<NuzlockeTask> tasks = loadShippedQuestTasks();

		assertFalse(tasks.isEmpty(), "Quest_Tasks.json loaded ZERO tasks — check the region-group wrapper");
		assertTrue(tasks.size() > 150, "expected the full quest pool, got " + tasks.size());
	}

	@Test
	void everyQuestTaskResolves() throws Exception
	{
		for (NuzlockeTask task : loadShippedQuestTasks())
		{
			assertEquals("QUEST_CHECK", task.getCompletionType(), task.getTaskId());
			assertNotNull(task.getConstraints(), "no constraints on " + task.getTaskId());

			String questName = task.getConstraints().getQuest();
			assertNotNull(questName, "constraints.quest did not deserialize for " + task.getTaskId());

			// Quest.valueOf is what the module calls; a name the enum doesn't
			// have would make the task silently untrackable at runtime.
			assertDoesNotThrow(() -> Quest.valueOf(questName),
				"unknown Quest constant '" + questName + "' on " + task.getTaskId());
		}
	}

	@Test
	void shippedQuestTaskIdsAreUniqueAndPointsInRange() throws Exception
	{
		Set<String> seen = new HashSet<>();
		for (NuzlockeTask task : loadShippedQuestTasks())
		{
			assertTrue(seen.add(task.getTaskId()), "duplicate taskID: " + task.getTaskId());
			assertTrue(task.getBasePoints() >= 1 && task.getBasePoints() <= 5,
				task.getTaskId() + " has base_points " + task.getBasePoints());
		}
	}

	@Test
	void excludedQuestsAreAbsent() throws Exception
	{
		Set<String> excluded = new HashSet<>();
		excluded.add("LEARNING_THE_ROPES");
		excluded.add("CURRENT_AFFAIRS");
		excluded.add("PRYING_TIMES");
		excluded.add("PANDEMONIUM");
		excluded.add("TROUBLED_TORTUGANS");
		excluded.add("THE_RED_REEF");

		for (NuzlockeTask task : loadShippedQuestTasks())
		{
			assertFalse(excluded.contains(task.getConstraints().getQuest()),
				"excluded quest present: " + task.getConstraints().getQuest());
		}
	}

	// ---------------------------------------------------------------
	// Module behaviour
	// ---------------------------------------------------------------

	@Test
	void completesTaskWhenQuestIsFinished()
	{
		lenient().when(client.getGameState()).thenReturn(GameState.LOGGED_IN);
		lenient().when(client.getIntStack()).thenReturn(STACK_FINISHED);

		NuzlockeTask task = questTask("quest_cooks_assistant", "COOKS_ASSISTANT");
		questCheckModule.addActiveTask(task);

		advanceAndSweep();

		assertTrue(task.isCompleted(), "task should complete when the quest reports FINISHED");
		assertEquals(1, task.getCurrentProgress());
		verify(completionCallback).onTaskCompleted(task, 1);
	}

	@Test
	void doesNotCompleteWhenQuestNotStarted()
	{
		lenient().when(client.getGameState()).thenReturn(GameState.LOGGED_IN);
		lenient().when(client.getIntStack()).thenReturn(STACK_NOT_STARTED);

		NuzlockeTask task = questTask("quest_cooks_assistant", "COOKS_ASSISTANT");
		questCheckModule.addActiveTask(task);

		advanceAndSweep();

		assertFalse(task.isCompleted());
		verify(completionCallback, never()).onTaskCompleted(any(), anyInt());
	}

	@Test
	void doesNotCompleteWhenQuestInProgress()
	{
		lenient().when(client.getGameState()).thenReturn(GameState.LOGGED_IN);
		lenient().when(client.getIntStack()).thenReturn(STACK_IN_PROGRESS);

		NuzlockeTask task = questTask("quest_dragon_slayer_ii", "DRAGON_SLAYER_II");
		questCheckModule.addActiveTask(task);

		advanceAndSweep();

		assertFalse(task.isCompleted());
		verify(completionCallback, never()).onTaskCompleted(any(), anyInt());
	}

	@Test
	void doesNotRunScriptsWhenLoggedOut()
	{
		lenient().when(client.getGameState()).thenReturn(GameState.LOGIN_SCREEN);

		NuzlockeTask task = questTask("quest_cooks_assistant", "COOKS_ASSISTANT");
		questCheckModule.addActiveTask(task);

		advanceAndSweep();

		assertFalse(task.isCompleted());
		// getState() would have run a script; the login gate must stop it.
		verify(client, never()).runScript(any(Object[].class));
		verify(completionCallback, never()).onTaskCompleted(any(), anyInt());
	}

	@Test
	void unknownQuestIsIgnoredSafely()
	{
		NuzlockeTask task = questTask("quest_not_a_real_quest", "THIS_QUEST_DOES_NOT_EXIST");

		assertDoesNotThrow(() -> questCheckModule.addActiveTask(task));
		assertFalse(questCheckModule.getActiveTasks().contains(task),
			"a task naming an unknown Quest constant must not be tracked");
	}

	@Test
	void missingQuestConstraintIsNotTracked()
	{
		NuzlockeTask task = questTask("quest_missing", "COOKS_ASSISTANT");
		task.setConstraints(new TaskConstraints()); // quest == null

		assertDoesNotThrow(() -> questCheckModule.addActiveTask(task));
		assertFalse(questCheckModule.getActiveTasks().contains(task));
	}

	@Test
	void varbitChangeAloneDoesNotSweep()
	{
		lenient().when(client.getGameState()).thenReturn(GameState.LOGGED_IN);
		lenient().when(client.getIntStack()).thenReturn(STACK_FINISHED);
		lenient().when(client.getTickCount()).thenReturn(0);

		NuzlockeTask task = questTask("quest_cooks_assistant", "COOKS_ASSISTANT");
		questCheckModule.addActiveTask(task);

		// A burst of varbit changes with no tick in between must not each
		// trigger a full ~200-task script sweep.
		for (int i = 0; i < 50; i++)
		{
			questCheckModule.onVarbitChanged(new VarbitChanged());
		}

		assertFalse(task.isCompleted(), "sweep should be deferred to onGameTick, not run per VarbitChanged");
	}

	@Test
	void completedTaskIsDroppedFromTracking()
	{
		lenient().when(client.getGameState()).thenReturn(GameState.LOGGED_IN);
		lenient().when(client.getIntStack()).thenReturn(STACK_FINISHED);

		NuzlockeTask task = questTask("quest_cooks_assistant", "COOKS_ASSISTANT");
		questCheckModule.addActiveTask(task);

		advanceAndSweep();
		assertTrue(task.isCompleted());

		// Second sweep must not re-fire the callback for the same task.
		advanceAndSweep();
		verify(completionCallback, times(1)).onTaskCompleted(task, 1);
	}

	/**
	 * Regression guard for the 2026-07-19 client freeze: ~150 quest tasks all
	 * completed in one sweep, and each completion runs an expensive per-task
	 * pipeline on the client thread (config writes + a full Swing rebuild).
	 * A single sweep must never fire more than the cap.
	 */
	@Test
	void sweepCapsCompletionsPerPass()
	{
		lenient().when(client.getGameState()).thenReturn(GameState.LOGGED_IN);
		lenient().when(client.getIntStack()).thenReturn(STACK_FINISHED);

		// 20 already-finished quests registered at once.
		String[] quests = {
			"COOKS_ASSISTANT", "DRAGON_SLAYER_I", "DEMON_SLAYER", "IMP_CATCHER",
			"SHEEP_SHEARER", "RUNE_MYSTERIES", "DORICS_QUEST", "WITCHS_POTION",
			"THE_RESTLESS_GHOST", "PIRATES_TREASURE", "GOBLIN_DIPLOMACY",
			"BLACK_KNIGHTS_FORTRESS", "VAMPYRE_SLAYER", "ERNEST_THE_CHICKEN",
			"PRINCE_ALI_RESCUE", "SHIELD_OF_ARRAV", "MISTHALIN_MYSTERY",
			"X_MARKS_THE_SPOT", "BELOW_ICE_MOUNTAIN", "THE_CORSAIR_CURSE",
		};
		for (int i = 0; i < quests.length; i++)
		{
			questCheckModule.addActiveTask(questTask("quest_" + i, quests[i]));
		}

		// Exactly one sweep.
		questCheckModule.onVarbitChanged(new VarbitChanged());
		lenient().when(client.getTickCount()).thenReturn(1000);
		questCheckModule.onGameTick(new GameTick());

		verify(completionCallback, atMost(5)).onTaskCompleted(any(), anyInt());
	}

	@Test
	void handlesQuestCheckCompletionType()
	{
		assertEquals("QUEST_CHECK", questCheckModule.getCompletionType());
		assertTrue(questCheckModule.canHandle(questTask("q", "COOKS_ASSISTANT")));
	}
}

